/* Kamiś 2.4 — Domowa Książka Kucharska, partia 1/10: 100 autorskich receptur.
    70 polskich i 30 z kuchni świata. Każda ilość na 1 porcję (jajka w szt.).
    Nie zmienia istniejących receptur ani klucza localStorage `kamis-v2`.
    Jest to test strukturalny i kontrola redakcyjna, nie test smaku w kuchni.
*/
(()=>{'use strict';
const domowePart1=[{"id":30000,"name":"Barszcz ukraiński z fasolą i kapustą","meal":"Obiad","kind":"veg","calories":376,"protein":12,"carbs":56,"fat":10,"ingredients":[["Buraki",140.0,0.63],["Kapusta biała",75.0,0.38],["Ziemniaki",90.0,0.41],["Fasola biała ugotowana",75.0,0.82],["Marchew",50.0,0.25],["Pietruszka korzeń",35.0,0.53],["Cebula",40.0,0.2],["Czosnek",5.0,0.07],["Koncentrat pomidorowy",12.0,0.1],["Olej rzepakowy",8.0,0.09],["Woda",550.0,0.0],["Liść laurowy",1.0,0.01],["Koperek",5.0,0.07],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Opłucz i obierz buraki, ziemniaki, marchew, pietruszkę i cebulę. Buraki zetrzyj na grubych oczkach, ziemniaki pokrój w kostkę 1,5 cm, kapustę poszatkuj.","Do garnka wlej 550 ml wody, dodaj marchew, pietruszkę, liść laurowy i połowę cebuli. Gotuj pod przykryciem na małym ogniu 20 minut; tak powstanie prosty wywar warzywny.","Na patelni rozgrzej olej. Resztę cebuli smaż 4 minuty, dodaj starte buraki, czosnek i koncentrat; podlej 3 łyżkami wywaru i duś 12 minut.","Do wywaru włóż ziemniaki i kapustę. Gotuj 15 minut, następnie dołóż podsmażone buraki i opłukaną, ugotowaną fasolę; gotuj następne 10 minut.","Dopraw solą, pieprzem i koperkiem. Nie blenduj: barszcz ukraiński powinien mieć wyraźne kawałki warzyw."],"minutes":100,"equipment":["pot","stove"],"cuisine":"polska","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":100},{"id":30001,"name":"Rosół drobiowy z własnym makaronem","meal":"Obiad","kind":"chicken","calories":611,"protein":55,"carbs":65,"fat":12,"ingredients":[["Kurczak z kością",180.0,4.68],["Marchew",70.0,0.35],["Pietruszka korzeń",40.0,0.6],["Seler korzeń",30.0,0.45],["Por",30.0,0.45],["Cebula",50.0,0.25],["Liść laurowy",1.0,0.01],["Ziele angielskie",2.0,0.03],["Woda",750.0,0.0],["Mąka pszenna",65.0,0.33],["Jajko",1.0,1.05],["Sól",3.0,0.0],["Natka pietruszki",5.0,0.07]],"steps":["Cebulę przekrój i opal na suchej patelni 3 minuty. Kurczaka włóż do garnka, zalej 750 ml zimnej wody, podgrzej prawie do wrzenia i zbierz szumowiny.","Dodaj obraną marchew, pietruszkę, seler, por, cebulę, liść laurowy i ziele angielskie. Gotuj bardzo łagodnie, bez gwałtownego wrzenia, 90 minut.","W tym czasie zagnieć mąkę z jajkiem i łyżką wody, aż ciasto będzie gładkie. Przykryj na 15 minut, potem rozwałkuj cienko i pokrój w nitki.","W osobnym garnku zagotuj osoloną wodę i gotuj świeży makaron 2–3 minuty. Odcedź.","Przecedź rosół, mięso oddziel od kości, marchew pokrój w plasterki. Podawaj z makaronem, mięsem, marchewką i natką."],"minutes":150,"equipment":["pot","stove"],"cuisine":"polska","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":150},{"id":30002,"name":"Żurek na zakwasie z białą kiełbasą i jajkiem","meal":"Obiad","kind":"pork","calories":626,"protein":27,"carbs":40,"fat":40,"ingredients":[["Zakwas żytni na żurek",160.0,2.4],["Biała kiełbasa surowa",110.0,4.51],["Ziemniaki",110.0,0.49],["Marchew",40.0,0.2],["Cebula",40.0,0.2],["Czosnek",5.0,0.07],["Majeranek",2.0,0.03],["Liść laurowy",1.0,0.01],["Ziele angielskie",2.0,0.03],["Woda",470.0,0.0],["Jajko",1.0,1.05],["Śmietana 18%",25.0,0.3],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Ziemniaki obierz i pokrój w kostkę. Cebulę posiekaj, marchew pokrój w plasterki, czosnek rozgnieć.","Wlej wodę do garnka, dodaj marchew, cebulę, liść laurowy, ziele angielskie i surową białą kiełbasę. Gotuj pod przykryciem na małym ogniu 25 minut.","Wyjmij kiełbasę. Do wywaru dodaj ziemniaki; gotuj 15 minut do miękkości. Jajko ugotuj osobno na twardo przez 9 minut od zagotowania.","Zakwas dokładnie wymieszaj i wlej cienkim strumieniem do zupy, mieszając. Gotuj łagodnie 5 minut, dodaj czosnek, majeranek i pieprz.","Śmietanę zahartuj dwiema łyżkami ciepłej zupy i wlej do garnka. Podawaj z pokrojoną kiełbasą i połówkami jajka."],"minutes":75,"equipment":["pot","stove"],"cuisine":"polska","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":75},{"id":30003,"name":"Zupa ogórkowa z ryżem i koperkiem","meal":"Obiad","kind":"veg","calories":477,"protein":9,"carbs":74,"fat":14,"ingredients":[["Ogórki kiszone",130.0,1.95],["Ryż suchy",50.0,0.5],["Marchew",55.0,0.28],["Pietruszka korzeń",35.0,0.53],["Ziemniaki",90.0,0.41],["Cebula",30.0,0.15],["Masło",10.0,0.55],["Śmietana 18%",25.0,0.3],["Koperek",7.0,0.1],["Woda",550.0,0.0],["Liść laurowy",1.0,0.01],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Obierz marchew, pietruszkę, ziemniaki i cebulę. Warzywa korzeniowe pokrój drobno, ziemniaki w kostkę, ogórki zetrzyj na tarce.","W garnku zagotuj wodę z marchwią, pietruszką, cebulą i liściem laurowym. Gotuj 15 minut, dodaj ziemniaki i opłukany ryż; gotuj 15 minut.","Na patelni rozpuść masło i duś starte ogórki 6–8 minut, żeby zmiękły. Dopiero teraz włóż je do zupy, bo kwas spowalnia mięknięcie ziemniaków.","Gotuj następne 5 minut. Śmietanę wymieszaj z łyżką gorącego wywaru, dodaj do garnka i delikatnie podgrzej.","Dopraw pieprzem i koperkiem. Z solą uważaj, ponieważ ogórki są już słone."],"minutes":55,"equipment":["pot","stove"],"cuisine":"polska","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":55},{"id":30004,"name":"Krupnik z kaszą jęczmienną i warzywami","meal":"Obiad","kind":"chicken","calories":488,"protein":34,"carbs":75,"fat":5,"ingredients":[["Kurczak z kością",100.0,2.6],["Kasza jęczmienna",65.0,0.65],["Ziemniaki",100.0,0.45],["Marchew",65.0,0.33],["Pietruszka korzeń",30.0,0.45],["Seler korzeń",25.0,0.38],["Por",30.0,0.45],["Woda",650.0,0.0],["Liść laurowy",1.0,0.01],["Natka pietruszki",6.0,0.09],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Kurczaka włóż do garnka z wodą, dodaj por i liść laurowy. Gotuj na małym ogniu 30 minut, zbierając pianę z powierzchni.","Kaszę opłucz na sicie. Marchew, pietruszkę i seler pokrój w drobną kostkę, ziemniaki w kostkę 1,5 cm.","Do garnka dołóż kaszę i warzywa korzeniowe. Gotuj 20 minut, następnie dodaj ziemniaki i gotuj dalsze 15–20 minut.","Wyjmij kurczaka, oddziel mięso od kości, rozdrobnij i wrzuć z powrotem do zupy.","Dopraw solą, pieprzem i natką. Podawaj gorący krupnik z widoczną, miękką kaszą i kawałkami mięsa."],"minutes":90,"equipment":["pot","stove"],"cuisine":"polska","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":90},{"id":30005,"name":"Kapuśniak z kiszonej kapusty na wędzonce","meal":"Obiad","kind":"pork","calories":261,"protein":7,"carbs":50,"fat":1,"ingredients":[["Kapusta kiszona",170.0,0.85],["Żeberka wędzone",140.0,5.04],["Ziemniaki",120.0,0.54],["Marchew",60.0,0.3],["Cebula",45.0,0.23],["Liść laurowy",1.0,0.01],["Ziele angielskie",2.0,0.03],["Kminek",1.0,0.01],["Woda",650.0,0.0],["Sól",1.0,0.0],["Pieprz",1.0,0.01]],"steps":["Żeberka włóż do garnka z 650 ml wody, liściem laurowym i zielem angielskim. Gotuj na małym ogniu 35–40 minut, aż oddadzą smak.","Obierz ziemniaki, marchew i cebulę. Ziemniaki pokrój w kostkę, marchew w półplasterki, cebulę drobno.","Do wywaru dodaj ziemniaki i marchew; gotuj 15 minut. Kapustę, jeśli jest bardzo kwaśna, lekko odciśnij i posiekaj.","Dodaj kapustę, cebulę i kminek. Gotuj 25–30 minut do miękkości kapusty, mieszając od czasu do czasu.","Wyjmij żeberka, oddziel mięso od kości i włóż do garnka. Dopraw pieprzem; dosalaj dopiero po spróbowaniu."],"minutes":95,"equipment":["pot","stove"],"cuisine":"polska","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":95},{"id":30006,"name":"Grochówka wojskowa z grochu łuskanego i kiełbasy","meal":"Obiad","kind":"pork","calories":775,"protein":37,"carbs":83,"fat":34,"ingredients":[["Groch łuskany",85.0,0.85],["Ziemniaki",130.0,0.58],["Kiełbasa wędzona",95.0,3.89],["Marchew",60.0,0.3],["Cebula",50.0,0.25],["Czosnek",5.0,0.07],["Majeranek",2.0,0.03],["Liść laurowy",1.0,0.01],["Olej rzepakowy",7.0,0.08],["Woda",720.0,0.0],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Groch kilkakrotnie opłucz. Wsyp go do garnka, zalej wodą, dodaj liść laurowy i gotuj na małym ogniu 45 minut, zbierając pianę.","Obierz ziemniaki i marchew. Pokrój je w kostkę; dodaj do grochu i gotuj następne 18–20 minut.","Na patelni rozgrzej olej. Pokrojoną kiełbasę smaż 4 minuty, dodaj cebulę i smaż dalsze 5 minut.","Do zupy dołóż kiełbasę z cebulą, roztarty czosnek i majeranek. Gotuj 8 minut; jeśli chcesz gęstszej zupy, rozgnieć część grochu tłuczkiem.","Dopraw solą i pieprzem. Nie blenduj całej zupy: tradycyjna grochówka ma wyczuwalne kawałki."],"minutes":105,"equipment":["pot","stove"],"cuisine":"polska","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":105},{"id":30007,"name":"Zupa grzybowa z suszonych borowików i łazanek","meal":"Obiad","kind":"veg","calories":472,"protein":12,"carbs":67,"fat":16,"ingredients":[["Grzyby suszone borowiki",25.0,0.38],["Makaron łazanki",75.0,0.9],["Marchew",50.0,0.25],["Pietruszka korzeń",30.0,0.45],["Cebula",50.0,0.25],["Masło",10.0,0.55],["Śmietana 18%",35.0,0.42],["Woda",650.0,0.0],["Natka pietruszki",6.0,0.09],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Suszone grzyby opłucz, zalej 250 ml wody i mocz 30 minut. Zachowaj płyn z moczenia; przelej go ostrożnie przez drobne sitko, by oddzielić piasek.","Marchew i pietruszkę pokrój w plasterki. Grzyby pokrój na mniejsze kawałki, cebulę posiekaj.","W garnku podgrzej masło, zeszklij cebulę przez 5 minut. Dodaj grzyby, warzywa, przecedzony płyn i pozostałe 400 ml wody.","Gotuj na małym ogniu 30 minut, aż grzyby zmiękną. W osobnej osolonej wodzie ugotuj łazanki zgodnie z czasem na opakowaniu i odcedź.","Śmietanę zahartuj gorącą zupą, dodaj do garnka i podgrzej bez silnego wrzenia. Podawaj z łazankami i natką."],"minutes":85,"equipment":["pot","stove"],"cuisine":"polska","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":85},{"id":30008,"name":"Kotlet schabowy w klasycznej panierce z ziemniakami","meal":"Obiad","kind":"pork","calories":856,"protein":53,"carbs":83,"fat":33,"ingredients":[["Schab bez kości",170.0,6.46],["Jajko",1.0,1.05],["Mąka pszenna",20.0,0.1],["Bułka tarta",35.0,0.24],["Smalec",18.0,0.27],["Ziemniaki",250.0,1.12],["Sól",3.0,0.0],["Pieprz",1.0,0.01],["Woda",500.0,0.0]],"steps":["Schab rozbij tłuczkiem między dwoma arkuszami folii na grubość około 7 mm. Osusz i dopraw solą oraz pieprzem.","Ziemniaki obierz, pokrój na zbliżone kawałki, zalej wodą, lekko posól i gotuj 18–22 minuty do miękkości.","Ustaw trzy talerze: mąka, roztrzepane jajko i bułka tarta. Kotlet obtocz kolejno w mące, jajku i bułce, dociskając panierkę.","Na patelni rozgrzej smalec. Smaż schab na średnim ogniu po 3–4 minuty z każdej strony do złocistej panierki i pełnego dosmażenia mięsa.","Osącz kotlet krótko na papierze, ziemniaki odcedź. Podaj razem bez polewania panierki sosem."],"minutes":45,"equipment":["stove","pot"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":45},{"id":30009,"name":"Kotlety mielone wieprzowe z podsmażaną cebulą","meal":"Obiad","kind":"pork","calories":421,"protein":14,"carbs":38,"fat":23,"ingredients":[["Mięso mielone wieprzowe",180.0,2.7],["Cebula",65.0,0.33],["Bułka czerstwa",40.0,0.6],["Mleko",65.0,0.26],["Jajko",1.0,1.05],["Bułka tarta",20.0,0.14],["Olej rzepakowy",15.0,0.17],["Majeranek",1.0,0.01],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Bułkę namocz w mleku na 8 minut, a następnie dobrze odciśnij. Cebulę pokrój drobno i zeszklij na 5 g oleju przez 5 minut.","Wymieszaj mięso mielone, odciśniętą bułkę, cebulę, jajko, majeranek, sól i pieprz. Wyrabiaj ręką 2 minuty, aż masa będzie zwarta.","Uformuj dwa spłaszczone kotlety i delikatnie obtocz je w bułce tartej.","Na patelni rozgrzej pozostały olej; smaż na umiarkowanym ogniu po 6–7 minut na stronę, aż kotlety będą rumiane i gorące w środku.","Po smażeniu odstaw na 3 minuty, żeby soki rozłożyły się równomiernie."],"minutes":45,"equipment":["stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":45},{"id":30010,"name":"Zrazy wołowe zawijane z ogórkiem i boczkiem","meal":"Obiad","kind":"beef","calories":693,"protein":49,"carbs":13,"fat":47,"ingredients":[["Wołowina z udźca",200.0,13.6],["Boczek wędzony",35.0,1.68],["Ogórek kiszony",55.0,0.55],["Cebula",60.0,0.3],["Musztarda",18.0,0.27],["Mąka pszenna",8.0,0.04],["Olej rzepakowy",12.0,0.13],["Woda",320.0,0.0],["Liść laurowy",1.0,0.01],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Plaster wołowiny rozbij na około 5 mm. Posmaruj musztardą, ułóż paski boczku, ogórka i połowę cebuli, zawiń ciasno i zabezpiecz wykałaczkami.","Na patelni rozgrzej olej i obsmaż zraz ze wszystkich stron przez 5–6 minut. Przełóż do rondla z resztą posiekanej cebuli.","Wlej wodę, dodaj liść laurowy, sól i pieprz. Duś pod przykryciem na małym ogniu 100–120 minut, obracając raz w połowie czasu.","Gdy mięso będzie miękkie, wyjmij zraz. Mąkę rozmieszaj z 2 łyżkami zimnego wywaru, wlej do sosu i gotuj 3 minuty.","Wyjmij wykałaczki, pokrój zraz ukośnie i podaj polany sosem z duszenia."],"minutes":155,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":155},{"id":30011,"name":"Rolada śląska z boczkiem i cebulą","meal":"Obiad","kind":"beef","calories":727,"protein":50,"carbs":16,"fat":50,"ingredients":[["Wołowina zrazowa",200.0,13.6],["Boczek wędzony",40.0,1.92],["Cebula",70.0,0.35],["Ogórek kiszony",55.0,0.55],["Musztarda",20.0,0.3],["Olej rzepakowy",12.0,0.13],["Mąka pszenna",10.0,0.05],["Woda",350.0,0.0],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Rozbij wołowinę na szeroki, cienki płat. Posmaruj musztardą, rozłóż plastry boczku, słupki ogórka i połowę cebuli.","Zwiń mięso w ścisłą roladę i obwiąż sznurkiem kuchennym. Rozgrzej olej w garnku i zrumień roladę na wszystkich stronach przez 6 minut.","Dodaj pozostałą cebulę i wodę, dopraw solą oraz pieprzem. Duś powoli pod przykryciem 110–120 minut, co jakiś czas przewracając.","Wyjmij roladę. Mąkę rozmieszaj z chłodną wodą, dodaj do płynu z duszenia i gotuj 4 minuty, tworząc sos.","Usuń sznurek i podawaj roladę w grubych plastrach z sosem; tradycyjnie pasują kluski śląskie."],"minutes":160,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":160},{"id":30012,"name":"Gulasz z łopatki wieprzowej z papryką i cebulą","meal":"Obiad","kind":"pork","calories":680,"protein":42,"carbs":25,"fat":43,"ingredients":[["Łopatka wieprzowa",200.0,6.4],["Cebula",95.0,0.47],["Papryka czerwona",120.0,1.44],["Koncentrat pomidorowy",18.0,0.14],["Czosnek",5.0,0.07],["Mąka pszenna",10.0,0.05],["Olej rzepakowy",12.0,0.13],["Woda",280.0,0.0],["Papryka słodka mielona",4.0,0.05],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Łopatkę pokrój w kostkę około 2,5 cm i osusz. Cebulę posiekaj, paprykę pokrój w paski, czosnek rozgnieć.","W garnku obsmaż mięso na oleju 6 minut partiami. Dodaj cebulę, smaż 5 minut, potem czosnek i paprykę mieloną na 30 sekund.","Dodaj koncentrat i wlej wodę. Duś pod przykryciem 65 minut na małym ogniu, po czym dodaj czerwoną paprykę.","Gotuj kolejne 20 minut. Mąkę rozprowadź w 40 ml zimnej wody i wlej do sosu; gotuj 3 minuty, aż zgęstnieje.","Dopraw solą i pieprzem. Mięso ma być miękkie, a sos gęsty, paprykowy."],"minutes":115,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":115},{"id":30013,"name":"Bitki wołowe w sosie własnym","meal":"Obiad","kind":"beef","calories":578,"protein":47,"carbs":18,"fat":33,"ingredients":[["Wołowina z udźca",210.0,14.28],["Cebula",95.0,0.47],["Olej rzepakowy",12.0,0.13],["Mąka pszenna",15.0,0.07],["Woda",400.0,0.0],["Liść laurowy",1.0,0.01],["Ziele angielskie",2.0,0.03],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Wołowinę pokrój w plastry grubości 1,5 cm i delikatnie rozbij. Oprósz połową mąki i pieprzem.","Na rozgrzanym oleju obsmaż plastry po 2 minuty z każdej strony, wyjmij. Cebulę pokrój w piórka i smaż 5 minut w tym samym naczyniu.","Włóż mięso z powrotem, dodaj wodę, liść laurowy i ziele angielskie. Duś pod przykryciem na małym ogniu 100–115 minut.","Sprawdź miękkość widelcem. Pozostałą mąkę wymieszaj z zimną wodą, dodaj do sosu i gotuj 4 minuty, mieszając.","Dopraw solą; podawaj bitki polane naturalnym sosem cebulowym."],"minutes":145,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":145},{"id":30014,"name":"Pieczeń rzymska z jajkiem w środku","meal":"Obiad","kind":"pork","calories":447,"protein":21,"carbs":43,"fat":20,"ingredients":[["Mięso mielone wieprzowe",200.0,3.0],["Jajko",2.0,2.1],["Bułka tarta",30.0,0.21],["Cebula",65.0,0.33],["Czosnek",5.0,0.07],["Mleko",40.0,0.16],["Olej rzepakowy",8.0,0.09],["Majeranek",1.0,0.01],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Jedno jajko ugotuj na twardo 9 minut, ostudź i obierz. Cebulę posiekaj i podsmaż na oleju 4 minuty.","Mięso połącz z drugim surowym jajkiem, mlekiem, bułką tartą, cebulą, rozgniecionym czosnkiem i przyprawami; wyrabiaj 2 minuty.","Na folii uformuj płaski prostokąt z mięsa. Połóż ugotowane jajko w środku, szczelnie otul farszem, formując podłużny bochenek.","Przełóż do niewielkiej natłuszczonej formy i piecz 45–50 minut w 180°C, aż środek pieczeni osiągnie co najmniej 71°C.","Odczekaj 10 minut przed krojeniem, aby przekrój z jajkiem zachował kształt."],"minutes":90,"equipment":["oven","pot"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":90},{"id":30015,"name":"Kaczka pieczona z jabłkami i majerankiem","meal":"Obiad","kind":"poultry","calories":899,"protein":71,"carbs":18,"fat":58,"ingredients":[["Kaczka, porcja ze skórą i kością",380.0,22.42],["Jabłka",170.0,1.02],["Cebula",70.0,0.35],["Majeranek",3.0,0.04],["Czosnek",5.0,0.07],["Sól",4.0,0.0],["Pieprz",1.0,0.01],["Woda",130.0,0.0]],"steps":["Kaczkę osusz, skórę delikatnie nakłuj w kilku miejscach, nie uszkadzając mięsa. Natrzyj solą, pieprzem, majerankiem i czosnkiem.","Jabłka pokrój w ósemki, usuń gniazda nasienne. Cebulę pokrój w duże kawałki; ułóż wszystko w naczyniu żaroodpornym, połóż kaczkę skórą do góry.","Wlej wodę na dno, nakryj naczynie. Piecz w 165°C przez 110 minut, następnie zdejmij przykrycie.","Podnieś temperaturę do 205°C i dopiekaj 20–30 minut, aż skóra się zrumieni, a mięso przy kości osiągnie bezpieczną temperaturę co najmniej 74°C.","Przed podaniem pozostaw mięso na 10 minut. Podaj z jabłkami z pieczenia."],"minutes":185,"equipment":["oven"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":185},{"id":30016,"name":"Kurczak pieczony z masłem czosnkowo-ziołowym","meal":"Obiad","kind":"chicken","calories":872,"protein":60,"carbs":35,"fat":53,"ingredients":[["Udko z kurczaka ze skórą",290.0,7.54],["Masło",25.0,1.38],["Czosnek",8.0,0.12],["Natka pietruszki",8.0,0.12],["Tymianek",2.0,0.03],["Cytryna",40.0,0.48],["Sól",3.0,0.0],["Pieprz",1.0,0.01],["Ziemniaki",180.0,0.81]],"steps":["Ziemniaki umyj i pokrój na ćwiartki. Czosnek posiekaj, wymieszaj z miękkim masłem, natką, tymiankiem i skórką otartą z cytryny.","Udko osusz i delikatnie podważ skórę. Wsuń połowę masła pod skórę, pozostałą porcją natrzyj zewnętrzną stronę; dopraw solą i pieprzem.","W naczyniu ułóż ziemniaki i udko, skrop sokiem z cytryny. Piecz w 190°C przez 45–55 minut.","W połowie pieczenia przewróć ziemniaki; nie polewaj skóry wodą, jeśli ma być rumiana. Temperatura wewnętrzna mięsa przy kości powinna osiągnąć co najmniej 74°C.","Odstaw na 5 minut, podawaj z pieczonymi ziemniakami i sokami z naczynia."],"minutes":75,"equipment":["oven"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":75},{"id":30017,"name":"Kotlet de volaille z płynnym masłem pietruszkowym","meal":"Obiad","kind":"chicken","calories":1099,"protein":61,"carbs":52,"fat":71,"ingredients":[["Pierś z kurczaka",210.0,5.46],["Masło",35.0,1.93],["Natka pietruszki",9.0,0.14],["Czosnek",4.0,0.06],["Mąka pszenna",25.0,0.12],["Jajko",1.0,1.05],["Bułka tarta",45.0,0.31],["Olej rzepakowy",30.0,0.33],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Zimne masło wymieszaj z posiekaną natką i czosnkiem, uformuj wałeczek i zamroź na 15 minut. Filet rozbij cienko między arkuszami folii.","Połóż masło na środku mięsa, zawiń brzegi do środka i uformuj szczelną roladkę. Dopraw z zewnątrz solą oraz pieprzem.","Panieruj kolejno w mące, jajku i bułce tartej. Powtórz jajko i bułkę przy złączeniach, żeby masło nie wypłynęło.","Na oleju smaż delikatnie, obracając, 6–8 minut do złotego koloru. Następnie dopiecz 10–12 minut w piekarniku 180°C do minimum 74°C w środku mięsa.","Odstaw na 3 minuty. Przekrój ostrożnie: gorące masło może wypłynąć."],"minutes":60,"equipment":["stove","oven"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":60},{"id":30018,"name":"Gołąbki z mięsem i ryżem w sosie pomidorowym","meal":"Obiad","kind":"pork","calories":508,"protein":11,"carbs":86,"fat":11,"ingredients":[["Kapusta biała",200.0,1.0],["Mięso mielone wieprzowe",160.0,2.4],["Ryż suchy",60.0,0.6],["Cebula",60.0,0.3],["Pomidory przecier",170.0,1.36],["Olej rzepakowy",9.0,0.1],["Woda",250.0,0.0],["Sól",3.0,0.0],["Pieprz",1.0,0.01],["Majeranek",1.0,0.01]],"steps":["Z główki kapusty oddziel 2–3 duże liście. Blanszuj we wrzątku 5 minut, odetnij twarde zgrubienia. Ryż ugotuj w osolonej wodzie przez 10 minut i odcedź.","Posiekaną cebulę zeszklij na oleju przez 5 minut. Wymieszaj ją z mielonym mięsem, podgotowanym ryżem, majerankiem, solą i pieprzem.","Na każdy liść połóż porcję farszu, złóż boki i ciasno zwiń. Ułóż gołąbki złączeniem w dół w garnku wyłożonym mniejszymi liśćmi kapusty.","Wymieszaj pomidorowy przecier z wodą i wlej do garnka. Przykryj i duś na małym ogniu 60–70 minut, aż kapusta będzie miękka i mięso ugotowane.","Z sosu odlej łyżkę do spróbowania i dopraw. Podawaj gołąbki polane sosem pomidorowym."],"minutes":130,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":130},{"id":30019,"name":"Żeberka wieprzowe duszone z cebulą i czosnkiem","meal":"Obiad","kind":"pork","calories":331,"protein":6,"carbs":36,"fat":16,"ingredients":[["Żeberka wieprzowe surowe",360.0,12.96],["Cebula",140.0,0.7],["Czosnek",10.0,0.15],["Olej rzepakowy",14.0,0.15],["Woda",260.0,0.0],["Liść laurowy",1.0,0.01],["Majeranek",2.0,0.03],["Sól",4.0,0.0],["Pieprz",1.0,0.01]],"steps":["Żeberka podziel między kośćmi na porcje. Osusz papierem i natrzyj solą, pieprzem i majerankiem.","Na rozgrzanym oleju zrumień żeberka przez 6–8 minut z każdej strony. Odłóż na chwilę na talerz.","Cebulę pokrój w piórka, podsmaż w tym samym garnku 7 minut. Dodaj posiekany czosnek na 30 sekund.","Włóż żeberka do garnka, dodaj wodę i liść laurowy. Duś pod przykryciem 90–105 minut, aż mięso będzie odchodzić od kości.","Zdejmij pokrywkę i odparuj sos przez 5 minut. Podawaj z miękką cebulą i sosem."],"minutes":145,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":145},{"id":30020,"name":"Udka kurczaka w sosie koperkowo-śmietanowym","meal":"Obiad","kind":"chicken","calories":633,"protein":42,"carbs":14,"fat":44,"ingredients":[["Udko z kurczaka bez skóry i kości",200.0,5.2],["Cebula",55.0,0.28],["Śmietana 18%",65.0,0.78],["Koperek",12.0,0.18],["Masło",12.0,0.66],["Mąka pszenna",8.0,0.04],["Woda",180.0,0.0],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Kurczaka osusz, pokrój na duże kawałki i dopraw solą oraz pieprzem. Cebulę drobno posiekaj.","Na patelni rozpuść masło, obsmaż kawałki kurczaka przez 6 minut, dodaj cebulę i smaż 4 minuty.","Dolej wodę, przykryj i duś 20 minut. Sprawdź, czy drób osiągnął w środku minimum 74°C.","Śmietanę połącz z mąką i 2 łyżkami gorącego płynu, wlej do patelni, mieszając. Gotuj łagodnie 3–4 minuty do zagęszczenia.","Dodaj posiekany koperek dopiero na koniec. Podawaj z sosem, nie doprowadzając go do silnego wrzenia."],"minutes":65,"equipment":["stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":65},{"id":30021,"name":"Szynka wieprzowa pieczona z kminkiem","meal":"Obiad","kind":"pork","calories":252,"protein":4,"carbs":26,"fat":13,"ingredients":[["Szynka wieprzowa surowa",250.0,9.5],["Czosnek",8.0,0.12],["Kminek",3.0,0.04],["Musztarda",20.0,0.3],["Olej rzepakowy",12.0,0.13],["Cebula",80.0,0.4],["Woda",120.0,0.0],["Sól",4.0,0.0],["Pieprz",1.0,0.01]],"steps":["Szynkę osusz i natrzyj solą, pieprzem, zmiażdżonym czosnkiem, kminkiem, musztardą i olejem. Pozostaw na 20 minut.","Cebulę pokrój w ćwiartki. Przełóż mięso i cebulę do naczynia z pokrywką, dolej wodę na dno.","Piecz w 175°C pod przykryciem przez około 65–75 minut. Zdejmij pokrywkę i dopiekaj 10 minut, aż powierzchnia się zrumieni.","Sprawdź temperaturę wewnętrzną w najgrubszym miejscu mięsa — powinna osiągnąć co najmniej 63°C, a następnie odstaw mięso na 3 minuty.","Pokrój poprzecznie do włókien. Podaj z cebulą i sokami z pieczenia."],"minutes":130,"equipment":["oven"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":130},{"id":30022,"name":"Bigos staropolski z kapusty mieszanej i wędzonek","meal":"Obiad","kind":"pork","calories":792,"protein":41,"carbs":35,"fat":52,"ingredients":[["Kapusta kiszona",200.0,1.0],["Kapusta biała",140.0,0.7],["Łopatka wieprzowa",110.0,3.52],["Kiełbasa wędzona",70.0,2.87],["Boczek wędzony",35.0,1.68],["Grzyby suszone",12.0,0.18],["Śliwki suszone",30.0,0.27],["Cebula",70.0,0.35],["Koncentrat pomidorowy",18.0,0.14],["Woda",320.0,0.0],["Liść laurowy",1.0,0.01],["Ziele angielskie",2.0,0.03],["Pieprz",1.0,0.01]],"steps":["Grzyby opłucz i namocz w 100 ml wody przez 25 minut. Kapustę białą poszatkuj, kiszoną odciśnij tylko jeśli jest bardzo kwaśna.","Łopatkę pokrój w kostkę, boczek i kiełbasę w plasterki, cebulę posiekaj. Na suchej patelni wytop boczek, dodaj mięso i obsmaż 7 minut, potem cebulę i kiełbasę.","Włóż obie kapusty do dużego garnka, dodaj mięso, pokrojone grzyby, śliwki, liść laurowy, ziele angielskie oraz wodę z grzybów po przecedzeniu.","Dolej pozostałą wodę i duś pod przykryciem 90 minut, co 15 minut mieszając, aby dno się nie przypaliło.","Dodaj koncentrat i pieprz, gotuj jeszcze 20 minut bez przykrycia. Najlepiej podgrzej ponownie następnego dnia; nie jest to konieczne do podania."],"minutes":175,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":175},{"id":30023,"name":"Potrawka z indyka w białym sosie z groszkiem","meal":"Obiad","kind":"chicken","calories":469,"protein":50,"carbs":26,"fat":19,"ingredients":[["Filet z indyka",180.0,8.46],["Marchew",80.0,0.4],["Groszek zielony",70.0,1.05],["Masło",15.0,0.82],["Mąka pszenna",12.0,0.06],["Mleko",100.0,0.4],["Woda",220.0,0.0],["Sok z cytryny",12.0,0.14],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Indyka pokrój w równą kostkę 2 cm. Marchew obierz i pokrój w małą kostkę.","Mięso włóż do garnka, dodaj wodę i marchew. Zagotuj i gotuj na małym ogniu 15 minut, następnie dodaj groszek na 5 minut.","W drugim rondlu rozpuść masło, wsyp mąkę i mieszaj minutę. Stopniowo dolewaj mleko oraz 100 ml gorącego wywaru z indyka, cały czas mieszając.","Gotuj biały sos 4 minuty, następnie dodaj ugotowane mięso i warzywa. Podgrzej 3 minuty, sprawdzając minimum 74°C wewnątrz indyka.","Dopraw sokiem z cytryny, solą i pieprzem. Sos powinien oblepiać kawałki mięsa, ale nadal się rozpływać."],"minutes":60,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":60},{"id":30024,"name":"Gulasz drobiowy z papryką, cukinią i pomidorami","meal":"Obiad","kind":"chicken","calories":494,"protein":47,"carbs":29,"fat":19,"ingredients":[["Pierś z kurczaka",190.0,4.94],["Papryka czerwona",100.0,1.2],["Cukinia",120.0,1.32],["Cebula",65.0,0.33],["Pomidory krojone",160.0,1.28],["Czosnek",6.0,0.09],["Olej rzepakowy",12.0,0.13],["Papryka słodka mielona",4.0,0.05],["Woda",100.0,0.0],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Kurczaka pokrój w kostkę 2 cm. Paprykę i cukinię pokrój na podobnej wielkości kawałki, cebulę posiekaj.","Na oleju obsmaż kurczaka 5 minut, dodaj cebulę i smaż kolejne 4 minuty. Dołóż czosnek i mieloną paprykę na 30 sekund.","Wlej pomidory i wodę. Gotuj na umiarkowanym ogniu 10 minut, po czym dodaj paprykę oraz cukinię.","Duś pod przykryciem 15–18 minut, aż warzywa będą miękkie, a drób w środku osiągnie co najmniej 74°C.","Dopraw solą i pieprzem. Podawaj jako gęsty gulasz warzywno-mięsny."],"minutes":60,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":60},{"id":30025,"name":"Dorsz panierowany w bułce tartej","meal":"Obiad","kind":"fish","calories":632,"protein":47,"carbs":43,"fat":30,"ingredients":[["Filet z dorsza",190.0,11.4],["Mąka pszenna",20.0,0.1],["Jajko",1.0,1.05],["Bułka tarta",35.0,0.24],["Olej rzepakowy",22.0,0.24],["Cytryna",35.0,0.42],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Filet z dorsza dokładnie osusz i sprawdź palcami, czy nie ma ości. Pokrój na dwie równe porcje, dopraw solą i pieprzem.","Przygotuj trzy talerze: mąka, roztrzepane jajko, bułka tarta. Filet obtocz w tej kolejności, lekko dociskając panierkę.","Na średnim ogniu rozgrzej olej na patelni. Smaż rybę około 3–4 minuty z każdej strony, zależnie od grubości, aż panierka będzie złocista, a mięso całkowicie nieprzezroczyste.","Sprawdź, czy ryba osiągnęła w środku co najmniej 63°C. Zdejmij na kratkę lub papier na minutę.","Podawaj z kawałkiem cytryny, którą wyciśniesz dopiero tuż przed jedzeniem."],"minutes":35,"equipment":["stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":35},{"id":30026,"name":"Karp pieczony z cebulą i majerankiem","meal":"Obiad","kind":"fish","calories":526,"protein":49,"carbs":11,"fat":30,"ingredients":[["Dzwonko karpia",260.0,9.88],["Cebula",110.0,0.55],["Czosnek",5.0,0.07],["Olej rzepakowy",14.0,0.15],["Majeranek",2.0,0.03],["Cytryna",40.0,0.48],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Karpia opłucz i osusz, sprawdź ości. Natrzyj solą, pieprzem, majerankiem i przeciśniętym czosnkiem.","Cebulę pokrój w grube piórka, wymieszaj z olejem i rozłóż na dnie naczynia żaroodpornego.","Połóż rybę na cebuli, skrop połową soku z cytryny. Piecz w piekarniku rozgrzanym do 185°C przez 25–30 minut.","Sprawdź, czy ryba jest gotowa w najgrubszym miejscu i osiąga minimum 63°C; mięso powinno łatwo rozdzielać się na płatki.","Podawaj z pieczoną cebulą i pozostałą cytryną."],"minutes":70,"equipment":["oven"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":70},{"id":30027,"name":"Śledzie w śmietanie z jabłkiem i cebulą","meal":"Kolacja","kind":"fish","calories":564,"protein":32,"carbs":16,"fat":41,"ingredients":[["Filety śledziowe solone",150.0,5.1],["Śmietana 18%",90.0,1.08],["Jabłko",110.0,0.66],["Cebula",55.0,0.28],["Sok z cytryny",12.0,0.14],["Pieprz",1.0,0.01],["Koperek",6.0,0.09]],"steps":["Jeśli śledzie są mocno słone, namocz je 20–30 minut w zimnej wodzie i spróbuj; w razie potrzeby wymień wodę. Następnie osusz.","Pokrój śledzie na kawałki około 3 cm. Jabłko obierz, usuń gniazdo nasienne i pokrój w małą kostkę; cebulę posiekaj drobno.","Śmietanę wymieszaj z sokiem z cytryny, pieprzem i posiekanym koperkiem. Połącz z jabłkiem i cebulą.","Dodaj śledzie, ostrożnie wymieszaj i wstaw do lodówki na 15 minut, aby smaki się połączyły.","Podawaj schłodzone. Nie dosalaj bez spróbowania śledzi."],"minutes":45,"equipment":[],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":45},{"id":30028,"name":"Klopsiki wieprzowe w sosie koperkowym","meal":"Obiad","kind":"pork","calories":400,"protein":15,"carbs":43,"fat":18,"ingredients":[["Mięso mielone wieprzowe",180.0,2.7],["Jajko",1.0,1.05],["Bułka tarta",20.0,0.14],["Cebula",40.0,0.2],["Koperek",14.0,0.21],["Masło",12.0,0.66],["Mąka pszenna",10.0,0.05],["Mleko",80.0,0.32],["Woda",200.0,0.0],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Mięso wymieszaj z jajkiem, bułką tartą, drobno posiekaną cebulą, solą i pieprzem. Uformuj 4 małe klopsiki.","W garnku zagotuj wodę, zmniejsz ogień i gotuj klopsiki łagodnie około 15 minut, aż środek będzie w pełni ugotowany. Wyjmij je łyżką cedzakową.","W rondlu rozpuść masło, wsyp mąkę i mieszaj minutę. Stopniowo wlej mleko oraz 100 ml wywaru z gotowania klopsików.","Gotuj 4 minuty, mieszając, aż sos zgęstnieje. Dodaj posiekany koperek i klopsiki; podgrzewaj kolejne 3 minuty.","Podawaj mięso polane sosem koperkowym; przed podaniem upewnij się, że środek klopsików jest bezpiecznie ugotowany."],"minutes":60,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":60},{"id":30029,"name":"Karkówka pieczona z cebulą i musztardą","meal":"Obiad","kind":"pork","calories":757,"protein":41,"carbs":12,"fat":61,"ingredients":[["Karkówka wieprzowa",230.0,8.51],["Cebula",140.0,0.7],["Musztarda",25.0,0.38],["Czosnek",6.0,0.09],["Olej rzepakowy",10.0,0.11],["Woda",80.0,0.0],["Sól",3.0,0.0],["Pieprz",1.0,0.01],["Majeranek",2.0,0.03]],"steps":["Karkówkę pokrój na 2 grube plastry i natrzyj musztardą, majerankiem, solą, pieprzem i rozgniecionym czosnkiem.","Cebulę pokrój w piórka i rozłóż w naczyniu do pieczenia, wymieszaj z olejem. Na wierzchu ułóż mięso, wlej wodę na dno.","Przykryj i piecz w 175°C przez 65 minut. Następnie zdejmij pokrywkę i piecz kolejne 15–20 minut do zrumienienia.","Sprawdź, czy mięso jest miękkie, a jego temperatura w środku osiągnęła przynajmniej 63°C. Pozostaw na 3 minuty przed podaniem.","Podawaj z cebulą i sosem z dna naczynia, nie polewając nim mięsa przed zrumienieniem."],"minutes":110,"equipment":["oven"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":110},{"id":30030,"name":"Kaszanka smażona z cebulą i jabłkiem","meal":"Obiad","kind":"pork","calories":1007,"protein":30,"carbs":178,"fat":19,"ingredients":[["Kaszanka",220.0,2.2],["Cebula",120.0,0.6],["Jabłko",150.0,0.9],["Masło",10.0,0.55],["Olej rzepakowy",6.0,0.07],["Majeranek",2.0,0.03],["Pieprz",1.0,0.01]],"steps":["Cebulę obierz i pokrój w piórka. Jabłko przekrój na ćwiartki, usuń gniazdo nasienne, pokrój w plasterki.","Na patelni rozgrzej olej z masłem, smaż cebulę 7–8 minut na średnim ogniu, aż stanie się szklista i lekko złocista.","Dodaj jabłko i majeranek, smaż kolejne 5 minut. Przesuń dodatki na bok patelni.","Kaszankę podziel na grube plastry, podsmaż po 3–4 minuty z każdej strony, aż będzie cała gorąca. Możesz też ogrzewać ją w osłonce, jeśli jest przeznaczona do smażenia.","Posyp pieprzem i podawaj od razu z ciepłym jabłkiem oraz cebulą."],"minutes":30,"equipment":["stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":30},{"id":30031,"name":"Wątróbka drobiowa z cebulą i kwaśnym jabłkiem","meal":"Obiad","kind":"chicken","calories":399,"protein":7,"carbs":40,"fat":22,"ingredients":[["Wątróbka drobiowa",200.0,4.2],["Cebula",110.0,0.55],["Jabłko",100.0,0.6],["Mąka pszenna",15.0,0.07],["Olej rzepakowy",12.0,0.13],["Masło",10.0,0.55],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Wątróbkę oczyść z błonek i dokładnie osusz. Cebulę pokrój w piórka, jabłko w ósemki bez gniazda nasiennego.","Na oleju z masłem smaż cebulę 7 minut, dodaj jabłko na 4 minuty i przełóż na talerz.","Wątróbkę lekko oprósz mąką, ułóż na patelni pojedynczą warstwą. Smaż po 4–5 minut z każdej strony, aż będzie w pełni ścięta w środku.","Sprawdź termometrem, że drobiowa wątróbka osiągnęła co najmniej 74°C. Dodaj cebulę i jabłko, podgrzej razem minutę.","Posól na koniec, dopraw pieprzem i podawaj od razu."],"minutes":35,"equipment":["stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":35},{"id":30032,"name":"Flaczki wołowe w tradycyjnym wywarze warzywnym","meal":"Obiad","kind":"beef","calories":542,"protein":43,"carbs":21,"fat":30,"ingredients":[["Flaki wołowe oczyszczone i wstępnie gotowane",190.0,12.92],["Marchew",60.0,0.3],["Pietruszka korzeń",35.0,0.53],["Seler korzeń",25.0,0.38],["Cebula",60.0,0.3],["Masło",12.0,0.66],["Mąka pszenna",10.0,0.05],["Woda",500.0,0.0],["Majeranek",2.0,0.03],["Imbir mielony",1.0,0.01],["Gałka muszkatołowa",1.0,0.01],["Liść laurowy",1.0,0.01],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Oczyszczone, wstępnie obgotowane flaki przepłucz na sicie. Jeśli kupione flaki nie były gotowane, przygotuj je najpierw zgodnie z instrukcją producenta, aż staną się miękkie.","Marchew, pietruszkę i seler obierz i zetrzyj na grubych oczkach; cebulę posiekaj. Zalej warzywa wodą z liściem laurowym i gotuj 20 minut.","Dodaj flaki i gotuj łagodnie 45–60 minut, aż będą miękkie. Na osobnej patelni zrób jasną zasmażkę z masła i mąki przez 2 minuty.","Rozprowadź zasmażkę kilkoma łyżkami gorącej zupy i wlej do garnka, energicznie mieszając. Gotuj jeszcze 5 minut.","Dopraw majerankiem, imbirem, gałką, solą i pieprzem. Flaczki podawaj gorące, z wyraźnie miękkimi paskami flaków."],"minutes":135,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":135},{"id":30033,"name":"Pierogi ruskie z ziemniakami, twarogiem i cebulą","meal":"Obiad","kind":"veg","calories":864,"protein":35,"carbs":123,"fat":25,"ingredients":[["Mąka pszenna",110.0,0.55],["Woda",60.0,0.0],["Olej rzepakowy",8.0,0.09],["Ziemniaki",180.0,0.81],["Twaróg półtłusty",110.0,2.75],["Cebula",75.0,0.38],["Masło",12.0,0.66],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Ziemniaki obierz, ugotuj w osolonej wodzie 20 minut, odcedź i dokładnie utłucz. Cebulę posiekaj i podsmaż na maśle 7 minut.","Wymieszaj ziemniaki z rozkruszonym twarogiem, cebulą, pieprzem i solą. Ostudź farsz, aby nie rozmiękczał ciasta.","Mąkę wymieszaj z ciepłą wodą, olejem i szczyptą soli; wyrabiaj 7 minut na elastyczne ciasto. Przykryj i odstaw na 20 minut.","Rozwałkuj ciasto na 2 mm, wytnij krążki szklanką. Na każdym umieść łyżeczkę farszu, sklej dokładnie brzegi.","Wrzucaj partiami do wrzącej osolonej wody; gotuj około 3 minuty od wypłynięcia. Podawaj gorące."],"minutes":105,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":105},{"id":30034,"name":"Pierogi z kapustą kiszoną i suszonymi grzybami","meal":"Obiad","kind":"veg","calories":715,"protein":15,"carbs":108,"fat":22,"ingredients":[["Mąka pszenna",115.0,0.57],["Woda",70.0,0.0],["Olej rzepakowy",8.0,0.09],["Kapusta kiszona",200.0,1.0],["Grzyby suszone",25.0,0.38],["Cebula",80.0,0.4],["Masło",15.0,0.82],["Liść laurowy",1.0,0.01],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Grzyby opłucz, namocz 25 minut w 150 ml wody, ugotuj w niej 20 minut i posiekaj. Kapustę odciśnij, posiekaj i gotuj w niewielkiej ilości wody z liściem laurowym przez 30 minut.","Cebulę zeszklij na maśle 7 minut. Wymieszaj z odciśniętą kapustą i grzybami; smaż farsz 5 minut, dopraw pieprzem i ostudź.","Zagnieć mąkę z ciepłą wodą, olejem i solą. Wyrabiaj 7 minut, przykryj i odstaw na 20 minut.","Rozwałkuj ciasto cienko, wytnij krążki, nałóż farsz i dokładnie sklej brzegi.","Gotuj partiami w lekko osolonej wodzie przez 3–4 minuty od wypłynięcia. Podawaj z odrobiną masła z patelni."],"minutes":125,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":125},{"id":30035,"name":"Pierogi z mięsem z gotowanego rosołu","meal":"Obiad","kind":"chicken","calories":822,"protein":50,"carbs":91,"fat":27,"ingredients":[["Mąka pszenna",115.0,0.57],["Woda",65.0,0.0],["Olej rzepakowy",8.0,0.09],["Gotowane mięso kurczaka bez kości",170.0,4.42],["Cebula",65.0,0.33],["Masło",15.0,0.82],["Woda do farszu",40.0,0.0],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Kurczaka ugotowanego i pozbawionego kości bardzo drobno posiekaj lub zmiel. Cebulę podsmaż na maśle 6 minut, wymieszaj z mięsem i 40 ml wody; dopraw.","Z mąki, 65 ml ciepłej wody, oleju i soli zagnieć elastyczne ciasto przez 7 minut. Przykryj miską na 20 minut.","Ciasto rozwałkuj na 2 mm, wytnij krążki, nałóż po łyżeczce wystudzonego farszu i starannie zlep brzegi.","Zagotuj dużą ilość lekko osolonej wody i wkładaj pierogi partiami, mieszając po wrzuceniu, by nie przylegały do dna.","Gotuj 3 minuty od wypłynięcia, wyjmij łyżką cedzakową i podawaj na ciepło."],"minutes":105,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":105},{"id":30036,"name":"Kopytka ziemniaczane z masłem i szałwią","meal":"Obiad","kind":"veg","calories":777,"protein":22,"carbs":123,"fat":21,"ingredients":[["Ziemniaki",300.0,1.35],["Mąka pszenna",95.0,0.47],["Jajko",1.0,1.05],["Masło",18.0,0.99],["Szałwia",4.0,0.06],["Sól",3.0,0.0],["Woda",800.0,0.0]],"steps":["Ziemniaki obierz, pokrój i gotuj w osolonej wodzie 20 minut. Odcedź bardzo dokładnie i przeciśnij przez praskę; pozostaw do ostudzenia.","Do chłodnych ziemniaków dodaj jajko i mąkę, szybko połącz w miękkie ciasto. Nie wyrabiaj długo, żeby nie stało się kleiste.","Podziel ciasto na wałki grubości około 2 cm, lekko spłaszcz i pokrój ukośnie na kopytka po 3 cm.","Gotuj w osolonej wodzie 2–3 minuty od wypłynięcia. W tym czasie na patelni podgrzej masło z szałwią przez 2 minuty.","Wyjmij kopytka, odparuj na sicie i delikatnie wymieszaj z masłem szałwiowym."],"minutes":65,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":65},{"id":30037,"name":"Kluski śląskie z dziurką","meal":"Obiad","kind":"veg","calories":721,"protein":22,"carbs":124,"fat":14,"ingredients":[["Ziemniaki",330.0,1.49],["Mąka ziemniaczana",90.0,0.45],["Jajko",1.0,1.05],["Masło",10.0,0.55],["Sól",3.0,0.0],["Woda",800.0,0.0]],"steps":["Ziemniaki obierz, ugotuj do miękkości około 20 minut, odcedź i przeciśnij przez praskę. Ostudź, aby para odparowała.","Ziemniaki wyrównaj w misce, wyjmij jedną czwartą i w wolne miejsce nasyp mąkę ziemniaczaną. Dodaj wyjęte ziemniaki, jajko i szczyptę soli.","Szybko zagnieć gładkie ciasto. Odrywaj małe porcje, formuj kulki i w każdej zrób palcem wgłębienie.","Wrzuć kluski partiami do delikatnie wrzącej osolonej wody. Gotuj około 2 minuty od wypłynięcia.","Odcedź łyżką cedzakową i wymieszaj delikatnie z roztopionym masłem."],"minutes":55,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":55},{"id":30038,"name":"Pyzy ziemniaczane z farszem mięsnym","meal":"Obiad","kind":"pork","calories":644,"protein":15,"carbs":117,"fat":11,"ingredients":[["Ziemniaki surowe",250.0,1.12],["Ziemniaki ugotowane",150.0,0.68],["Mąka ziemniaczana",45.0,0.23],["Mięso mielone wieprzowe",150.0,2.25],["Cebula",65.0,0.33],["Olej rzepakowy",10.0,0.11],["Sól",3.0,0.0],["Pieprz",1.0,0.01],["Woda",800.0,0.0]],"steps":["Ugotowane ziemniaki przeciśnij przez praskę. Surowe obierz, zetrzyj drobno i mocno odciśnij przez ściereczkę; zachowaj skrobię osiadłą na dnie soku.","Cebulę posiekaj i podsmaż na oleju 5 minut, dodaj mięso i smaż 10 minut do pełnego ścięcia. Dopraw solą i pieprzem, ostudź.","Wymieszaj surowe i gotowane ziemniaki z mąką ziemniaczaną oraz odłożoną skrobią. Z ciasta formuj placuszki, do środka wkładaj łyżkę farszu.","Zlep ciasto w kulki o średnicy 5 cm. Wrzucaj ostrożnie do dużego garnka z delikatnie wrzącą osoloną wodą.","Gotuj na małym ogniu 15–20 minut po wypłynięciu, aż kluski będą sprężyste. Podawaj gorące."],"minutes":120,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":120},{"id":30039,"name":"Gołąbki jarskie z kaszą gryczaną i pieczarkami","meal":"Obiad","kind":"veg","calories":609,"protein":21,"carbs":97,"fat":15,"ingredients":[["Kapusta biała",240.0,1.2],["Kasza gryczana",85.0,0.85],["Pieczarki",160.0,1.92],["Cebula",75.0,0.38],["Olej rzepakowy",12.0,0.13],["Pomidory przecier",170.0,1.36],["Woda",280.0,0.0],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Liście kapusty sparz we wrzątku przez 5 minut, odetnij grube nerwy. Kaszę gryczaną ugotuj w osolonej wodzie przez 15 minut i odcedź.","Cebulę i pieczarki drobno posiekaj. Smaż na oleju 10–12 minut, aż odparuje woda; wymieszaj z kaszą, dopraw solą i pieprzem.","Na liście kapusty nałóż porcje farszu, zawiń brzegi do środka i uformuj zwarte gołąbki.","Ułóż w garnku złączeniem w dół, dolej wodę i przecier pomidorowy. Duś pod przykryciem 45–55 minut, aż kapusta będzie miękka.","Przed podaniem nabierz sos łyżką i polej nim gołąbki."],"minutes":110,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":110},{"id":30040,"name":"Placki ziemniaczane z cebulą i kwaśną śmietaną","meal":"Obiad","kind":"veg","calories":773,"protein":18,"carbs":85,"fat":39,"ingredients":[["Ziemniaki",340.0,1.53],["Cebula",70.0,0.35],["Jajko",1.0,1.05],["Mąka pszenna",25.0,0.12],["Olej rzepakowy",22.0,0.24],["Śmietana 18%",65.0,0.78],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Obierz ziemniaki i cebulę, zetrzyj je na małych oczkach. Odsącz nadmiar soku, a skrobię z dna miski pozostaw w masie.","Dodaj jajko, mąkę, sól i pieprz. Wymieszaj; masa powinna być gęsta i dawać się nakładać łyżką bez rozpływania.","Na patelni rozgrzej połowę oleju. Nakładaj porcje masy i rozprowadź na placki o grubości około 5 mm.","Smaż partiami po 3–4 minuty z każdej strony na średnim ogniu, dodając olej w razie potrzeby. Odsącz na kratce.","Podawaj natychmiast z zimną kwaśną śmietaną."],"minutes":40,"equipment":["stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":40},{"id":30041,"name":"Krokiety z pieczarkami i serem","meal":"Obiad","kind":"veg","calories":1218,"protein":55,"carbs":120,"fat":60,"ingredients":[["Mąka pszenna",95.0,0.47],["Mleko",170.0,0.68],["Jajko",2.0,2.1],["Woda",60.0,0.0],["Pieczarki",180.0,2.16],["Cebula",65.0,0.33],["Ser żółty",65.0,1.69],["Bułka tarta",40.0,0.28],["Olej rzepakowy",25.0,0.28],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Z mąki, mleka, wody i jednego jajka przygotuj gładkie ciasto naleśnikowe. Odstaw na 10 minut i usmaż 2–3 cienkie naleśniki na niewielkiej ilości oleju.","Pieczarki i cebulę drobno pokrój. Smaż 10 minut na patelni, aż odparuje płyn; dodaj starty ser, pieprz i szczyptę soli.","Farsz podziel między naleśniki. Złóż boki i zawiń ciasne krokiety tak, aby nadzienie nie wypływało.","Drugie jajko roztrzep na talerzu, na drugi wsyp bułkę tartą. Każdy krokiet obtocz w jajku i bułce tartej.","Smaż na pozostałym oleju z każdej strony około 3 minuty do złocistej skórki i rozgrzania środka."],"minutes":80,"equipment":["stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":80},{"id":30042,"name":"Naleśniki ze szpinakiem, czosnkiem i twarogiem","meal":"Obiad","kind":"veg","calories":812,"protein":41,"carbs":93,"fat":30,"ingredients":[["Mąka pszenna",90.0,0.45],["Mleko",170.0,0.68],["Jajko",1.0,1.05],["Woda",50.0,0.0],["Szpinak świeży",170.0,3.74],["Twaróg półtłusty",100.0,2.5],["Czosnek",7.0,0.1],["Olej rzepakowy",15.0,0.17],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Z mąki, mleka, jajka i wody przygotuj lejące, jednolite ciasto. Odstaw na 10 minut; na lekko natłuszczonej patelni usmaż dwa cienkie naleśniki.","Szpinak opłucz i osusz. Na pozostałym oleju podsmaż rozdrobniony czosnek 20 sekund, dodaj szpinak i smaż 3–4 minuty, aż zwiędnie.","Odsącz szpinak, wymieszaj z rozkruszonym twarogiem, solą i pieprzem.","Rozłóż farsz na naleśnikach, złóż je w koperty i ułóż na patelni złączeniem w dół.","Podgrzewaj na małym ogniu 2–3 minuty z każdej strony. Podawaj gorące, z farszem w środku."],"minutes":55,"equipment":["stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":55},{"id":30043,"name":"Racuchy drożdżowe z jabłkami","meal":"Obiad","kind":"veg","calories":870,"protein":25,"carbs":125,"fat":29,"ingredients":[["Mąka pszenna",120.0,0.6],["Mleko",110.0,0.44],["Drożdże świeże",12.0,0.19],["Cukier",18.0,0.07],["Jajko",1.0,1.05],["Jabłko",140.0,0.84],["Olej rzepakowy",20.0,0.22],["Sól",1.0,0.0]],"steps":["Mleko podgrzej do około 35°C, rozpuść w nim drożdże z łyżeczką cukru i łyżką mąki. Odstaw na 10 minut do spienienia.","Do miski wsyp resztę mąki, cukru i sól, dodaj jajko oraz zaczyn. Wymieszaj na gęste, lekko klejące ciasto i odstaw pod przykryciem 35 minut do wyrośnięcia.","Jabłko obierz, usuń gniazdo nasienne i pokrój w drobną kostkę. Wymieszaj delikatnie z wyrośniętym ciastem.","Na patelni rozgrzej olej. Nakładaj łyżką małe porcje i smaż po około 3 minuty na stronę na średnio małym ogniu.","Przekrój jednego racucha: środek powinien być puszysty i upieczony, nie płynny. Podawaj na ciepło."],"minutes":90,"equipment":["stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":90},{"id":30044,"name":"Łazanki z kiszoną kapustą i suszonymi grzybami","meal":"Obiad","kind":"veg","calories":623,"protein":16,"carbs":97,"fat":18,"ingredients":[["Makaron łazanki",105.0,1.26],["Kapusta kiszona",190.0,0.95],["Grzyby suszone",20.0,0.3],["Cebula",85.0,0.42],["Masło",18.0,0.99],["Liść laurowy",1.0,0.01],["Woda",250.0,0.0],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Grzyby zalej 150 ml wody i mocz 20 minut, potem gotuj 20 minut w tej samej wodzie. Wyjmij i pokrój drobno, płyn przecedź.","Kapustę posiekaj i duś z liściem laurowym, grzybami oraz wodą z moczenia przez 25 minut, do miękkości.","Na patelni rozpuść masło i smaż posiekaną cebulę 8 minut do złotego koloru. Dodaj kapustę z grzybami i smaż razem 5 minut.","Łazanki ugotuj w osobnej osolonej wodzie zgodnie z czasem na opakowaniu; odcedź.","Połącz makaron z kapustą, wymieszaj i podgrzewaj 2 minuty. Dopraw pieprzem i solą."],"minutes":80,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":80},{"id":30045,"name":"Kluski leniwe z twarogu i masła","meal":"Obiad","kind":"veg","calories":860,"protein":57,"carbs":83,"fat":34,"ingredients":[["Twaróg półtłusty",230.0,5.75],["Mąka pszenna",70.0,0.35],["Jajko",1.0,1.05],["Masło",20.0,1.1],["Bułka tarta",15.0,0.1],["Cukier",10.0,0.04],["Sól",1.0,0.0],["Woda",700.0,0.0]],"steps":["Twaróg rozgnieć widelcem lub przeciśnij przez praskę, aby nie było grudek. Wymieszaj z jajkiem, szczyptą soli, mąką i połową cukru.","Zagnieć krótko miękkie ciasto; gdy mocno się klei, oprósz blat odrobiną mąki, ale nie dodawaj jej bez potrzeby.","Podziel ciasto na wałki grubości 2 cm, spłaszcz nożem i pokrój ukośnie na kawałki po 3 cm.","Wrzucaj kluski partiami do wrzącej osolonej wody. Gotuj około 2 minuty od wypłynięcia, wyjmij łyżką cedzakową.","Na patelni zrumień bułkę tartą na maśle przez 2 minuty. Polej kluski i posyp pozostałym cukrem."],"minutes":45,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":45},{"id":30046,"name":"Knedle ziemniaczane ze śliwkami","meal":"Obiad","kind":"veg","calories":956,"protein":26,"carbs":158,"fat":23,"ingredients":[["Ziemniaki",290.0,1.3],["Mąka pszenna",90.0,0.45],["Jajko",1.0,1.05],["Śliwki świeże",160.0,1.44],["Cukier",15.0,0.06],["Masło",20.0,1.1],["Bułka tarta",20.0,0.14],["Sól",1.0,0.0],["Woda",700.0,0.0]],"steps":["Ziemniaki ugotuj do miękkości około 20 minut, odcedź, przeciśnij przez praskę i całkowicie ostudź.","Śliwki umyj, natnij wzdłuż i usuń pestki. Do każdej włóż szczyptę cukru.","Zagnieć ziemniaki z jajkiem, mąką i solą. Podziel na kawałki; każdy rozpłaszcz w dłoni i zawiń ciasno wokół śliwki, bez dziur.","Knedle wrzucaj partiami do delikatnie wrzącej wody. Gotuj 4–5 minut od wypłynięcia.","Na patelni rozpuść masło, podsmaż bułkę tartą 2 minuty. Polej knedle i podawaj na ciepło."],"minutes":85,"equipment":["pot","stove"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":85},{"id":30047,"name":"Zapiekanka ziemniaczana z brokułem i serem","meal":"Obiad","kind":"veg","calories":905,"protein":36,"carbs":68,"fat":53,"ingredients":[["Ziemniaki",290.0,1.3],["Brokuł",190.0,2.85],["Ser żółty",80.0,2.08],["Śmietana 18%",90.0,1.08],["Jajko",1.0,1.05],["Czosnek",5.0,0.07],["Masło",10.0,0.55],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Ziemniaki obierz, pokrój w cienkie plastry i podgotuj 8 minut w osolonej wodzie. Brokuł podziel na różyczki i zblanszuj we wrzątku 3 minuty.","Naczynie żaroodporne posmaruj masłem. Ułóż naprzemiennie ziemniaki i brokuł, przesypując połową startego sera.","Śmietanę wymieszaj z jajkiem, przeciśniętym czosnkiem, solą i pieprzem. Polej warzywa równomiernie.","Posyp resztą sera, przykryj folią i piecz w 185°C przez 25 minut; zdejmij folię i piecz następne 12–15 minut do zrumienienia.","Przed krojeniem odstaw na 5 minut, aby masa się ustabilizowała."],"minutes":80,"equipment":["oven","pot"],"cuisine":"polska","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":80},{"id":30048,"name":"Jajecznica na maśle ze szczypiorkiem i pomidorami","meal":"Śniadanie","kind":"egg","calories":415,"protein":22,"carbs":17,"fat":27,"ingredients":[["Jajko",3.0,3.15],["Masło",15.0,0.82],["Szczypiorek",15.0,0.23],["Pomidor",120.0,0.96],["Chleb żytni",80.0,1.2],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Pomidora opłucz i pokrój w ćwiartki, szczypiorek drobno posiekaj. Jajka rozbij do miski, lekko wymieszaj widelcem.","Na patelni roztop masło na małym ogniu, wlej jajka i mieszaj powoli łopatką przez 3–5 minut.","Zdejmij z ognia, gdy jajecznica pozostaje kremowa, ale nie ma płynnego surowego jajka. Dodaj sól, pieprz i większość szczypiorku.","Podawaj od razu z pokrojonymi pomidorami i chlebem, posyp resztą szczypiorku."],"minutes":15,"equipment":["stove"],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":15},{"id":30049,"name":"Pasta jajeczna z musztardą i ogórkiem kiszonym","meal":"Śniadanie","kind":"egg","calories":375,"protein":15,"carbs":12,"fat":29,"ingredients":[["Jajko",2.0,2.1],["Majonez",25.0,0.38],["Musztarda",15.0,0.23],["Ogórek kiszony",65.0,0.65],["Szczypiorek",12.0,0.18],["Chleb razowy",100.0,1.5],["Pieprz",1.0,0.01],["Sól",1.0,0.0]],"steps":["Jajka włóż do garnka z zimną wodą, zagotuj i gotuj 9 minut. Przełóż do zimnej wody, obierz i drobno posiekaj.","Ogórek kiszony pokrój w bardzo małą kostkę i lekko odciśnij, żeby pasta nie była wodnista. Szczypiorek posiekaj.","Wymieszaj jajka z majonezem, musztardą, ogórkiem i szczypiorkiem. Rozgnieć część jajek widelcem dla kremowej konsystencji.","Dopraw pieprzem i ewentualnie odrobiną soli. Podaj pastę na kromkach chleba razowego."],"minutes":25,"equipment":["pot","stove"],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":25},{"id":30050,"name":"Twarożek domowy z rzodkiewką, szczypiorkiem i jogurtem","meal":"Śniadanie","kind":"veg","calories":357,"protein":37,"carbs":25,"fat":12,"ingredients":[["Twaróg półtłusty",180.0,4.5],["Jogurt naturalny",65.0,0.97],["Rzodkiewka",90.0,1.35],["Szczypiorek",18.0,0.27],["Chleb żytni",90.0,1.35],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Rzodkiewki dokładnie opłucz, odetnij końcówki i pokrój w drobną kostkę. Szczypiorek posiekaj.","Twaróg rozkrusz widelcem, dodaj jogurt i mieszaj do uzyskania kremowej konsystencji z drobnymi grudkami.","Wmieszaj rzodkiewkę i szczypiorek, dopraw solą oraz pieprzem.","Przełóż do miseczki i podawaj z chlebem żytnim. Przygotowany twarożek przechowuj w lodówce."],"minutes":15,"equipment":[],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":15},{"id":30051,"name":"Kasza manna na mleku z musem jabłkowo-cynamonowym","meal":"Śniadanie","kind":"breakfast","calories":489,"protein":17,"carbs":75,"fat":13,"ingredients":[["Mleko",280.0,1.12],["Kasza manna",55.0,0.55],["Jabłko",140.0,0.84],["Masło",8.0,0.44],["Cynamon",2.0,0.03],["Miód",12.0,0.3]],"steps":["Jabłko obierz, wytnij gniazdo nasienne i zetrzyj na grubych oczkach. Na małej patelni rozpuść masło i duś jabłko z cynamonem 7 minut.","Mleko wlej do rondelka i podgrzewaj, mieszając, aż będzie gorące, lecz jeszcze nie wykipi.","Wsypuj kaszę mannę cienkim strumieniem, energicznie mieszając trzepaczką, aby nie zrobiły się grudki.","Gotuj na małym ogniu 4–5 minut, stale mieszając, aż kasza wyraźnie zgęstnieje. Przelej do miski.","Nałóż na wierzch ciepły mus jabłkowy i polej miodem."],"minutes":20,"equipment":["stove","pot"],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":20},{"id":30052,"name":"Owsianka pieczona z gruszką i orzechami włoskimi","meal":"Śniadanie","kind":"breakfast","calories":641,"protein":26,"carbs":77,"fat":25,"ingredients":[["Płatki owsiane",75.0,0.53],["Mleko",140.0,0.56],["Jajko",1.0,1.05],["Gruszka",140.0,1.12],["Orzechy włoskie",20.0,1.0],["Miód",12.0,0.3],["Proszek do pieczenia",3.0,0.04],["Cynamon",2.0,0.03]],"steps":["Rozgrzej piekarnik do 180°C. Gruszkę umyj, usuń gniazdo nasienne i pokrój w drobną kostkę. Orzechy posiekaj.","W misce wymieszaj płatki owsiane z mlekiem, jajkiem, miodem, proszkiem i cynamonem. Wmieszaj większość gruszki.","Przelej masę do niewielkiego naczynia żaroodpornego, posyp pozostałą gruszką i orzechami.","Piecz 25–30 minut, aż wierzch się zetnie i lekko zrumieni. Odstaw na 5 minut przed jedzeniem."],"minutes":40,"equipment":["oven"],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":40},{"id":30053,"name":"Grzanki żytnie z pieczarkami i tymiankiem","meal":"Śniadanie","kind":"veg","calories":423,"protein":20,"carbs":19,"fat":30,"ingredients":[["Chleb żytni",110.0,1.65],["Pieczarki",190.0,2.28],["Cebula",65.0,0.33],["Masło",18.0,0.99],["Ser żółty",50.0,1.3],["Tymianek",2.0,0.03],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Pieczarki oczyść szczoteczką i pokrój w plasterki. Cebulę obierz i drobno posiekaj.","Na patelni roztop masło; cebulę smaż 5 minut, dodaj pieczarki i smaż 8–10 minut, aż odparuje woda. Dopraw tymiankiem, solą i pieprzem.","Kromki chleba podpiecz na suchej patelni po minucie na stronę albo w piekarniku 200°C przez 4 minuty.","Rozłóż ciepłe pieczarki na grzankach, posyp tartym serem i zapiecz w 200°C przez 4–5 minut do rozpuszczenia sera."],"minutes":30,"equipment":["stove","oven"],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":30},{"id":30054,"name":"Omlet serowy z pietruszką smażony pod przykryciem","meal":"Śniadanie","kind":"egg","calories":564,"protein":35,"carbs":14,"fat":41,"ingredients":[["Jajko",3.0,3.15],["Mleko",35.0,0.14],["Mąka pszenna",12.0,0.06],["Ser żółty",55.0,1.43],["Natka pietruszki",12.0,0.18],["Masło",12.0,0.66],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Jajka rozbij do miski i roztrzep z mlekiem, mąką, solą oraz pieprzem, aż nie będzie grudek mąki.","Ser zetrzyj na tarce, natkę drobno posiekaj. Połowę sera i natkę wmieszaj do masy jajecznej.","Na patelni 22–24 cm roztop masło na średnio małym ogniu. Wlej masę i smaż pod przykryciem przez 5–7 minut, aż góra przestanie być płynna.","Posyp resztą sera, złóż omlet na pół i podgrzewaj jeszcze minutę, aby ser się rozpuścił.","Przełóż na talerz jednym ruchem, nie mieszając masy podczas smażenia — to ma być omlet, nie jajecznica."],"minutes":20,"equipment":["stove"],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":20},{"id":30055,"name":"Jajka zapiekane w kokilkach ze szpinakiem","meal":"Śniadanie","kind":"egg","calories":456,"protein":24,"carbs":11,"fat":35,"ingredients":[["Jajko",2.0,2.1],["Szpinak świeży",110.0,2.42],["Śmietana 18%",35.0,0.42],["Ser żółty",35.0,0.91],["Masło",10.0,0.55],["Czosnek",5.0,0.07],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Piekarnik rozgrzej do 185°C. Szpinak opłucz i dobrze osusz. Czosnek drobno posiekaj.","Na patelni roztop połowę masła, podsmaż czosnek 20 sekund, dodaj szpinak i smaż 3 minuty do zwiędnięcia.","Kokilkę posmaruj resztą masła. Ułóż szpinak, wlej śmietanę, ostrożnie wbij jajka, starając się nie uszkodzić żółtek.","Posyp tartym serem i dopraw. Piecz 12–15 minut do ścięcia białek; przy potrzebie pełnego ścięcia żółtek dopiecz kilka minut.","Podawaj w kokilce, uważając na bardzo gorące naczynie."],"minutes":30,"equipment":["oven","stove"],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":30},{"id":30056,"name":"Kanapki z domową pastą z pieczonej papryki i fasoli","meal":"Śniadanie","kind":"veg","calories":358,"protein":12,"carbs":43,"fat":14,"ingredients":[["Chleb pełnoziarnisty",110.0,1.65],["Papryka czerwona",170.0,2.04],["Fasola biała ugotowana",110.0,1.21],["Czosnek",5.0,0.07],["Oliwa",12.0,0.48],["Sok z cytryny",12.0,0.14],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Paprykę umyj, przekrój i usuń gniazdo nasienne. Połóż skórką do góry na blasze i piecz 20 minut w 220°C, aż skórka miejscami ściemnieje.","Przełóż paprykę do przykrytej miski na 5 minut, następnie zdejmij skórkę i pokrój miąższ.","Fasolę odcedź i opłucz, jeśli jest z puszki. Zblenduj z papryką, czosnkiem, oliwą i sokiem z cytryny na gładką pastę.","Dopraw solą i pieprzem. Posmaruj kromki chleba grubą warstwą pasty i podawaj od razu."],"minutes":40,"equipment":["oven","blender"],"cuisine":"polska","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":40},{"id":30057,"name":"Sernik tradycyjny z twarogu i skórki cytrynowej","meal":"Deser","kind":"veg","calories":294,"protein":17,"carbs":26,"fat":13,"ingredients":[["Twaróg sernikowy",73.33,1.83],["Jajko",0.67,0.7],["Cukier",16.67,0.07],["Masło",6.67,0.37],["Mąka ziemniaczana",6.0,0.03],["Cytryna skórka",2.67,0.03],["Rodzynki",10.0,0.15]],"steps":["Ten przepis daje 3 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 220 g Twaróg sernikowy; 2 szt. Jajko; 50 g Cukier; 20 g Masło; 18 g Mąka ziemniaczana; 8 g Cytryna skórka; 30 g Rodzynki. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Rozgrzej piekarnik do 160°C. Twaróg przełóż do miski, masło roztop i lekko ostudź. Rodzynki opłucz i osusz.","Jajka roztrzep z cukrem przez 3 minuty, aż masa się rozjaśni. Dodaj twaróg, masło, mąkę ziemniaczaną i skórkę cytrynową, wymieszaj do połączenia.","Wmieszaj rodzynki. Masę przelej do niewielkiej formy wyłożonej papierem, wyrównaj powierzchnię.","Piecz w 160°C przez 55–65 minut, aż brzegi będą ścięte, a środek lekko sprężysty. Wyłącz piekarnik i pozostaw sernik przy uchylonych drzwiczkach 15 minut.","Wystudź całkowicie, a następnie schłódź co najmniej 2 godziny w lodówce przed krojeniem."],"minutes":245,"equipment":["oven"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":115,"k24BatchYield":3},{"id":30058,"name":"Szarlotka z kruchego ciasta i prażonych jabłek","meal":"Deser","kind":"veg","calories":369,"protein":6,"carbs":44,"fat":18,"ingredients":[["Mąka pszenna",32.5,0.16],["Masło",20.0,1.1],["Jajko",0.25,0.26],["Cukier",13.75,0.06],["Jabłka",75.0,0.45],["Cynamon",0.75,0.01],["Proszek do pieczenia",0.75,0.01],["Sok z cytryny",3.0,0.04]],"steps":["Ten przepis daje 4 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 130 g Mąka pszenna; 80 g Masło; 1 szt. Jajko; 55 g Cukier; 300 g Jabłka; 3 g Cynamon; 3 g Proszek do pieczenia; 12 g Sok z cytryny. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Z mąki, zimnego masła w kostce, połowy cukru, jajka i proszku szybko zagnieć kruche ciasto. Podziel na dwie części, schładzaj przez 20 minut.","Jabłka obierz, zetrzyj na grubych oczkach i praż na patelni przez 12–15 minut, aż nadmiar soku odparuje. Dodaj cynamon, sok z cytryny i resztę cukru.","Pierwszą częścią ciasta wyłóż dno niewielkiej formy i nakłuj widelcem. Podpiecz 10 minut w 185°C.","Na spód rozłóż ostudzone jabłka, na wierzch zetrzyj drugą część ciasta.","Piecz 30–35 minut w 185°C do złotego koloru. Ostudź co najmniej 20 minut przed krojeniem."],"minutes":125,"equipment":["oven","stove"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":105,"k24BatchYield":4},{"id":30059,"name":"Drożdżówka z kruszonką i budyniem waniliowym","meal":"Deser","kind":"veg","calories":564,"protein":12,"carbs":76,"fat":23,"ingredients":[["Mąka pszenna",62.5,0.31],["Mleko",62.5,0.25],["Drożdże świeże",6.5,0.1],["Cukier",24.0,0.1],["Masło",22.5,1.24],["Jajko",0.5,0.53],["Budyń waniliowy w proszku",12.5,0.19],["Sól",0.5,0.0]],"steps":["Ten przepis daje 2 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 125 g Mąka pszenna; 125 g Mleko; 13 g Drożdże świeże; 48 g Cukier; 45 g Masło; 1 szt. Jajko; 25 g Budyń waniliowy w proszku; 1 g Sól. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Z 75 ml letniego mleka, drożdży, łyżeczki cukru i łyżki mąki zrób zaczyn; odstaw na 10 minut. Resztę mleka zachowaj na budyń. Odłóż także 15 g mąki i 10 g cukru na kruszonkę.","Z pozostałych 110 g mąki, zaczynu, jajka, 25 g cukru, 25 g miękkiego masła i soli wyrabiaj ciasto 8 minut. Przykryj i odstaw na 45 minut do wyrośnięcia.","Z proszku budyniowego i pozostałego mleka ugotuj bardzo gęsty budyń, mieszając około 3 minuty; ostudź. Z pozostałych 20 g masła, odłożonych 15 g mąki i 10 g cukru zrób kruszonkę.","Wyrośnięte ciasto spłaszcz na placek, zostaw zagłębienie w środku, nałóż budyń i posyp kruszonką. Odstaw na 15 minut.","Piecz 22–28 minut w 180°C, aż boki będą rumiane i upieczone."],"minutes":135,"equipment":["oven","stove"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":135,"k24BatchYield":2},{"id":30060,"name":"Makowiec zawijany na cieście drożdżowym","meal":"Deser","kind":"veg","calories":315,"protein":7,"carbs":43,"fat":13,"ingredients":[["Mąka pszenna",30.0,0.15],["Mleko",20.0,0.08],["Drożdże świeże",3.0,0.05],["Masło",9.5,0.52],["Cukier",12.0,0.05],["Jajko",0.25,0.26],["Mak mielony suchy",23.75,0.36],["Miód",5.0,0.12],["Rodzynki",6.25,0.1],["Orzechy włoskie",5.0,0.25],["Sól",0.25,0.0]],"steps":["Ten przepis daje 4 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 120 g Mąka pszenna; 80 g Mleko; 12 g Drożdże świeże; 38 g Masło; 48 g Cukier; 1 szt. Jajko; 95 g Mak mielony suchy; 20 g Miód; 25 g Rodzynki; 20 g Orzechy włoskie; 1 g Sól. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Drożdże wymieszaj z 40 ml letniego mleka, łyżeczką cukru i mąki; odstaw na 10 minut. Z pozostałej mąki, mleka, jajka, 25 g masła, cukru i soli wyrabiaj ciasto 8 minut, odstaw na 50 minut.","Mak zalej wrzątkiem na 10 minut, odcedź bardzo dokładnie, połącz z miodem, rodzynkami, posiekanymi orzechami i resztą masła. Nadzienie musi być gęste, nie wodniste.","Ciasto rozwałkuj na prostokąt grubości 5 mm, rozsmaruj chłodną masę makową, zostaw wolny brzeg 2 cm. Zwiń w roladę, złączenie ułóż na dole.","Przełóż na papier do pieczenia, odstaw na 15 minut. Piecz w 180°C przez 35–40 minut.","Po upieczeniu odstaw na kratkę do wystudzenia przed krojeniem."],"minutes":175,"equipment":["oven","pot"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":175,"k24BatchYield":4},{"id":30061,"name":"Piernik miodowy z przyprawą korzenną","meal":"Deser","kind":"veg","calories":390,"protein":8,"carbs":59,"fat":13,"ingredients":[["Mąka pszenna",43.33,0.22],["Miód",21.67,0.54],["Masło",12.67,0.7],["Jajko",0.33,0.35],["Mleko",26.67,0.11],["Kakao",4.0,0.15],["Przyprawa do piernika",2.0,0.03],["Soda oczyszczona",1.0,0.01],["Cukier",6.67,0.03]],"steps":["Ten przepis daje 3 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 130 g Mąka pszenna; 65 g Miód; 38 g Masło; 1 szt. Jajko; 80 g Mleko; 12 g Kakao; 6 g Przyprawa do piernika; 3 g Soda oczyszczona; 20 g Cukier. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Piekarnik rozgrzej do 175°C. W rondelku rozpuść masło z miodem i cukrem na małym ogniu, nie doprowadzając do wrzenia; ostudź 5 minut.","W misce wymieszaj mąkę, kakao, sodę i przyprawę do piernika. W osobnym naczyniu roztrzep jajko z mlekiem.","Połącz płynne składniki z suchymi, wymieszaj tylko do zniknięcia suchej mąki. Przelej do niewielkiej keksówki wyłożonej papierem.","Piecz 40–45 minut w 175°C, aż patyczek wbity w środek będzie suchy.","Wystudź przez 15 minut w formie, następnie wyjmij na kratkę."],"minutes":100,"equipment":["oven","stove"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":85,"k24BatchYield":3},{"id":30062,"name":"Babka cytrynowa z lukrem","meal":"Deser","kind":"veg","calories":395,"protein":7,"carbs":50,"fat":18,"ingredients":[["Mąka pszenna",31.25,0.15],["Masło",18.75,1.03],["Cukier",18.75,0.07],["Jajko",0.5,0.53],["Cytryna",13.75,0.17],["Proszek do pieczenia",1.0,0.01],["Cukier puder",6.25,0.03],["Mleko",5.0,0.02]],"steps":["Ten przepis daje 4 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 125 g Mąka pszenna; 75 g Masło; 75 g Cukier; 2 szt. Jajko; 55 g Cytryna; 4 g Proszek do pieczenia; 25 g Cukier puder; 20 g Mleko. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Piekarnik rozgrzej do 175°C, małą formę na babkę posmaruj masłem lub wyłóż papierem. Umyj cytrynę, zetrzyj skórkę i wyciśnij sok.","Masło utrzyj z cukrem przez 4 minuty, wbijaj jajka pojedynczo. Dodaj skórkę cytrynową.","Wsyp mąkę z proszkiem i wlej mleko oraz połowę soku z cytryny; krótko wymieszaj na gładką masę.","Przełóż masę do formy i piecz 35–40 minut, aż patyczek wyjęty ze środka będzie suchy.","Pozostały sok cytrynowy wymieszaj z cukrem pudrem na gęsty lukier. Polej całkowicie wystudzoną babkę."],"minutes":100,"equipment":["oven"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":80,"k24BatchYield":4},{"id":30063,"name":"Karpatka z ciasta parzonego i kremu budyniowego","meal":"Deser","kind":"veg","calories":422,"protein":8,"carbs":42,"fat":24,"ingredients":[["Mąka pszenna",26.25,0.13],["Woda",30.0,0.0],["Masło",25.0,1.38],["Jajko",0.5,0.53],["Mleko",55.0,0.22],["Cukier",13.75,0.06],["Budyń waniliowy w proszku",10.0,0.15],["Cukier puder",5.0,0.02]],"steps":["Ten przepis daje 4 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 105 g Mąka pszenna; 120 g Woda; 100 g Masło; 2 szt. Jajko; 220 g Mleko; 55 g Cukier; 40 g Budyń waniliowy w proszku; 20 g Cukier puder. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","W rondlu zagotuj wodę z 35 g masła. Wsyp 105 g mąki i energicznie mieszaj 2 minuty, aż ciasto odchodzi od ścianek. Odstaw do przestudzenia.","Do letniego ciasta dodawaj jajka pojedynczo i ucieraj do uzyskania gęstej, lśniącej masy. Rozsmaruj na dwóch małych blaszkach, zostawiając nierówności.","Piecz każdą warstwę w 200°C przez 22–27 minut, nie otwierając piekarnika przez pierwsze 20 minut. Ostudź na kratce.","Z mleka, cukru i proszku budyniowego ugotuj gęsty budyń, mieszając 4–5 minut; wystudź do temperatury pokojowej. Utrzyj pozostałe masło i porcjami dodawaj budyń.","Rozsmaruj krem na jednym blacie, przykryj drugim i schładzaj 2 godziny. Przed podaniem oprósz cukrem pudrem."],"minutes":255,"equipment":["oven","stove"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":135,"k24BatchYield":4},{"id":30064,"name":"Pączki drożdżowe z konfiturą różaną","meal":"Deser","kind":"veg","calories":752,"protein":12,"carbs":94,"fat":36,"ingredients":[["Mąka pszenna",62.5,0.31],["Mleko",42.5,0.17],["Drożdże świeże",6.0,0.1],["Jajko",0.5,0.53],["Masło",12.5,0.69],["Cukier",17.5,0.07],["Konfitura różana",27.5,0.41],["Olej rzepakowy do smażenia",250.0,2.75],["Cukier puder",10.0,0.04],["Sól",0.5,0.0]],"steps":["Ten przepis daje 2 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 125 g Mąka pszenna; 85 g Mleko; 12 g Drożdże świeże; 1 szt. Jajko; 25 g Masło; 35 g Cukier; 55 g Konfitura różana; 500 g Olej rzepakowy do smażenia; 20 g Cukier puder; 1 g Sól. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Rozprowadź drożdże w letnim mleku z łyżeczką cukru i mąki, odstaw na 10 minut. Do zaczynu dodaj mąkę, jajko, resztę cukru, sól i miękkie masło; wyrabiaj 10 minut.","Przykryj ciasto i pozostaw w ciepłym miejscu na 60 minut, aż podwoi objętość. Podziel na 2–3 porcje i uformuj gładkie kulki, odstaw na 25 minut.","W głębokim rondlu rozgrzej olej do 170–175°C; sprawdź termometrem. Wkładaj pączki ostrożnie, smaż około 2,5–3 minuty na stronę.","Wyjmij na papier, po ostudzeniu wstrzyknij konfiturę różaną szprycą z długą końcówką.","Oprósz cukrem pudrem. Nie jedz pączków, jeśli w środku zostało surowe ciasto."],"minutes":165,"equipment":["stove"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":165,"k24BatchYield":2},{"id":30065,"name":"Faworki kruche z cukrem pudrem","meal":"Deser","kind":"veg","calories":479,"protein":6,"carbs":42,"fat":31,"ingredients":[["Mąka pszenna",41.67,0.21],["Żółtko",0.67,0.7],["Śmietana 18%",15.0,0.18],["Masło",4.0,0.22],["Ocet",2.0,0.03],["Olej rzepakowy do smażenia",166.67,1.83],["Cukier puder",10.0,0.04],["Sól",0.33,0.0]],"steps":["Ten przepis daje 3 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 125 g Mąka pszenna; 2 szt. Żółtko; 45 g Śmietana 18%; 12 g Masło; 6 g Ocet; 500 g Olej rzepakowy do smażenia; 30 g Cukier puder; 1 g Sól. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","W misce połącz mąkę, żółtka, śmietanę, miękkie masło, ocet i sól. Wyrabiaj 8 minut, aż ciasto będzie elastyczne.","Uderzaj ciasto wałkiem przez około 5 minut i kilkakrotnie je składaj, żeby napowietrzyć strukturę. Przykryj i odstaw na 20 minut.","Rozwałkuj na bardzo cienki placek, około 2 mm. Pokrój w paski 3 × 12 cm, natnij każdy środek i przewlecz przez nacięcie jeden koniec.","Rozgrzej olej do 175°C. Smaż faworki partiami po 40–60 sekund na stronę, aż będą jasnozłote i kruche.","Osącz na papierze, wystudź i posyp cukrem pudrem."],"minutes":75,"equipment":["stove"],"cuisine":"polska","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":75,"k24BatchYield":3},{"id":30066,"name":"Mizeria z ogórków i koperku","meal":"Dodatek","kind":"veg","calories":218,"protein":4,"carbs":16,"fat":15,"ingredients":[["Ogórek świeży",240.0,2.4],["Śmietana 18%",80.0,0.96],["Koperek",13.0,0.2],["Sok z cytryny",10.0,0.12],["Cukier",4.0,0.02],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Ogórki umyj i pokrój na bardzo cienkie plasterki, najlepiej mandoliną. Posyp szczyptą soli i odstaw na 8 minut.","Odlej wodę puszczoną przez ogórki, aby mizeria nie była rzadka. Koperek opłucz i drobno posiekaj.","Śmietanę wymieszaj z sokiem z cytryny, cukrem, pieprzem i koperkiem.","Połącz ogórki z sosem bezpośrednio przed podaniem. Schłodź 5 minut, jeśli wolisz zimną mizerię."],"minutes":20,"equipment":[],"cuisine":"polska","category24":"Dodatki i sosy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":20},{"id":30067,"name":"Ćwikła z buraków i świeżego chrzanu","meal":"Dodatek","kind":"veg","calories":167,"protein":4,"carbs":32,"fat":1,"ingredients":[["Buraki",260.0,1.17],["Chrzan świeżo starty",35.0,0.53],["Sok z cytryny",20.0,0.24],["Cukier",10.0,0.04],["Sól",2.0,0.0],["Woda",500.0,0.0]],"steps":["Buraki wyszoruj, nie obieraj. Zalej wodą i gotuj pod przykryciem około 45–55 minut, aż widelec wchodzi bez oporu.","Ostudź buraki, obierz ze skórki i zetrzyj na drobnych oczkach tarki.","Jeśli używasz świeżego korzenia chrzanu, obierz go i zetrzyj bardzo drobno, unikając wdychania ostrego zapachu.","Wymieszaj buraki z chrzanem, sokiem z cytryny, cukrem i solą. Schładzaj co najmniej 15 minut przed podaniem."],"minutes":75,"equipment":["pot","stove"],"cuisine":"polska","category24":"Dodatki i sosy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":75},{"id":30068,"name":"Surówka z kiszonej kapusty, marchewki i jabłka","meal":"Dodatek","kind":"veg","calories":296,"protein":5,"carbs":35,"fat":13,"ingredients":[["Kapusta kiszona",190.0,0.95],["Marchew",100.0,0.5],["Jabłko",110.0,0.66],["Cebula",35.0,0.17],["Olej rzepakowy",12.0,0.13],["Cukier",4.0,0.02],["Pieprz",1.0,0.01]],"steps":["Kapustę kiszoną spróbuj, w razie bardzo mocnej kwasowości lekko odciśnij i posiekaj.","Marchew obierz i zetrzyj na grubych oczkach, jabłko umyj i również zetrzyj po usunięciu gniazda nasiennego.","Cebulę bardzo drobno posiekaj. Połącz warzywa i jabłko z kapustą.","Dodaj olej, cukier i pieprz. Wymieszaj i odstaw na 10 minut, aby smaki się połączyły."],"minutes":20,"equipment":[],"cuisine":"polska","category24":"Dodatki i sosy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":20},{"id":30069,"name":"Domowy sos pieczarkowy do mięsa i klusek","meal":"Dodatek","kind":"veg","calories":417,"protein":11,"carbs":23,"fat":32,"ingredients":[["Pieczarki",200.0,2.4],["Cebula",70.0,0.35],["Masło",20.0,1.1],["Śmietana 18%",80.0,0.96],["Mąka pszenna",10.0,0.05],["Woda",180.0,0.0],["Natka pietruszki",8.0,0.12],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Pieczarki oczyść i pokrój w plasterki, cebulę posiekaj drobno. Na patelni roztop masło.","Smaż cebulę 5 minut, dodaj pieczarki i smaż 8–10 minut, aż odparuje większość ich wody.","Mąkę wymieszaj z 3 łyżkami zimnej wody. Dodaj pozostałą wodę do pieczarek i gotuj 4 minuty.","Wlej zawiesinę mączną, mieszając, i gotuj 3 minuty. Śmietanę zahartuj łyżką gorącego sosu, wlej i podgrzewaj jeszcze minutę.","Dopraw solą, pieprzem i natką; podawaj jako gęsty, ale lejący sos."],"minutes":30,"equipment":["stove"],"cuisine":"polska","category24":"Dodatki i sosy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":30},{"id":30070,"name":"Włoska minestrone z fasolą i drobnym makaronem","meal":"Obiad","kind":"veg","calories":585,"protein":20,"carbs":90,"fat":15,"ingredients":[["Fasola biała ugotowana",110.0,1.21],["Makaron drobny suchy",55.0,0.66],["Cukinia",100.0,1.1],["Marchew",55.0,0.28],["Seler naciowy",45.0,0.68],["Cebula",55.0,0.28],["Pomidory krojone",180.0,1.44],["Czosnek",6.0,0.09],["Oliwa",12.0,0.48],["Woda",450.0,0.0],["Bazylia",7.0,0.1],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Cebulę, marchew i seler naciowy pokrój w drobną kostkę, cukinię w półplasterki. Czosnek posiekaj.","W garnku rozgrzej oliwę, zeszklij cebulę 4 minuty, dodaj marchew i seler na 5 minut, potem czosnek na 30 sekund.","Dodaj pomidory i wodę, gotuj pod przykryciem 15 minut. Następnie wsyp suchy makaron, dodaj cukinię i gotuj tyle, ile zaleca opakowanie makaronu, zwykle 8–10 minut.","Dołóż odcedzoną, ugotowaną fasolę i gotuj 3 minuty. Dopraw solą, pieprzem i posiekaną bazylią.","Podawaj jako gęstą zupę z całymi warzywami, fasolą i makaronem."],"minutes":65,"equipment":["pot","stove"],"cuisine":"świat","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":65},{"id":30071,"name":"Wietnamska zupa pho ga z kurczakiem i ryżowym makaronem","meal":"Obiad","kind":"chicken","calories":779,"protein":63,"carbs":106,"fat":8,"ingredients":[["Kurczak z kością",200.0,5.2],["Makaron ryżowy",85.0,0.85],["Cebula",80.0,0.4],["Imbir świeży",25.0,0.38],["Anyż gwiazdkowy",2.0,0.03],["Cynamon laska",2.0,0.03],["Sos rybny",12.0,0.18],["Woda",800.0,0.0],["Limonka",35.0,0.53],["Kolendra świeża",12.0,0.18],["Kiełki fasoli mung",50.0,0.55],["Sól",1.0,0.0]],"steps":["Cebulę przekrój i podpiecz na suchej patelni przez 5 minut z plasterkami imbiru. Anyż i cynamon rozgrzewaj na patelni 30 sekund, aby uwolniły aromat.","Kurczaka włóż do garnka, dodaj cebulę, imbir, przyprawy i 800 ml wody. Zagotuj, zbierz pianę i gotuj łagodnie 65–75 minut.","Wyjmij kurczaka, oddziel mięso od kości, porwij na kawałki. Wywar przecedź przez sitko, dodaj sos rybny i dopraw.","Makaron ryżowy przygotuj w osobnym naczyniu zgodnie z instrukcją producenta, zwykle 5 minut w gorącej wodzie, i odcedź.","Rozłóż makaron, mięso, kiełki i kolendrę do miski; zalej bardzo gorącym wywarem. Podawaj z cząstkami limonki."],"minutes":110,"equipment":["pot","stove"],"cuisine":"świat","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":110},{"id":30072,"name":"Japoński ramen shoyu z jajkiem i wieprzowiną","meal":"Obiad","kind":"pork","calories":743,"protein":49,"carbs":83,"fat":21,"ingredients":[["Bulion drobiowy gotowy",450.0,6.75],["Makaron ramen",95.0,1.14],["Schab bez kości",120.0,4.56],["Jajko",1.0,1.05],["Sos sojowy",30.0,0.45],["Imbir świeży",12.0,0.18],["Czosnek",5.0,0.07],["Cebula dymka",30.0,0.15],["Grzyby shiitake",55.0,0.82],["Olej sezamowy",8.0,0.09],["Woda",300.0,0.0]],"steps":["Jajko ugotuj przez 7 minut od włożenia do wrzącej wody, przełóż do zimnej wody i obierz. Schab pokrój w cienkie plasterki.","W rondlu rozgrzej olej sezamowy, smaż posiekany czosnek i imbir 40 sekund. Dodaj shiitake i smaż 4 minuty.","Wlej gotowy bulion drobiowy i sos sojowy, gotuj na małym ogniu 15 minut. Jeśli używasz bulionu w koncentracie, rozcieńcz go wcześniej zgodnie z etykietą.","Na osobnej patelni usmaż cienkie plastry schabu po 2–3 minuty na stronę, aż będą w pełni gotowe. Makaron ugotuj w 300 ml wody zgodnie z opakowaniem i odcedź.","Do miski włóż makaron, mięso, przekrojone jajko i cebulę dymkę. Zalej gorącym wywarem z grzybami."],"minutes":100,"equipment":["pot","stove"],"cuisine":"świat","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":100},{"id":30073,"name":"Tajska tom kha gai z kurczakiem i mlekiem kokosowym","meal":"Obiad","kind":"chicken","calories":771,"protein":47,"carbs":23,"fat":54,"ingredients":[["Pierś z kurczaka",170.0,4.42],["Mleko kokosowe",240.0,0.96],["Woda",220.0,0.0],["Pieczarki",110.0,1.32],["Trawa cytrynowa",15.0,0.18],["Imbir świeży",14.0,0.21],["Limonka",45.0,0.68],["Sos rybny",15.0,0.23],["Papryczka chili",8.0,0.12],["Kolendra świeża",10.0,0.15],["Cukier",5.0,0.02]],"steps":["Kurczaka pokrój w cienkie plastry, pieczarki w ćwiartki. Trawę cytrynową rozgnieć bokiem noża, imbir pokrój w cienkie plasterki.","Do garnka wlej wodę i mleko kokosowe, dodaj trawę cytrynową oraz imbir. Podgrzewaj łagodnie przez 10 minut, nie dopuszczając do gwałtownego wrzenia.","Dodaj kurczaka i pieczarki, gotuj 10–12 minut, aż drób osiągnie w środku minimum 74°C.","Dopraw sosem rybnym, cukrem, cienko pokrojonym chili i sokiem z limonki. Wyjmij twarde łodygi trawy cytrynowej.","Przed podaniem posyp kolendrą. Zupa powinna być kremowa i wyraźnie kwaśno-pikantna."],"minutes":50,"equipment":["pot","stove"],"cuisine":"świat","category24":"Zupy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":50},{"id":30074,"name":"Lasagne bolognese z beszamelem","meal":"Obiad","kind":"beef","calories":1092,"protein":66,"carbs":54,"fat":67,"ingredients":[["Mięso mielone wołowe",180.0,12.24],["Płaty lasagne suche",95.0,1.43],["Passata pomidorowa",220.0,1.76],["Cebula",70.0,0.35],["Marchew",45.0,0.23],["Czosnek",6.0,0.09],["Oliwa",12.0,0.48],["Mleko",180.0,0.72],["Mąka pszenna",18.0,0.09],["Masło",18.0,0.99],["Ser żółty",60.0,1.56],["Sól",3.0,0.0],["Pieprz",1.0,0.01],["Oregano",2.0,0.03]],"steps":["Na oliwie podsmaż posiekaną cebulę i marchew 6 minut, dodaj czosnek na 30 sekund. Dołóż mieloną wołowinę i smaż 7 minut, rozdrabniając grudki.","Wlej passatę, dodaj oregano, sól i pieprz; gotuj sos boloński pod przykryciem 25 minut.","W rondlu roztop masło, wsyp mąkę i mieszaj minutę, następnie stopniowo wlewaj mleko. Gotuj 4 minuty do gęstego, gładkiego beszamelu.","Na dnie formy rozsmaruj warstwę sosu, ułóż płaty lasagne, beszamel i sos mięsny. Powtórz warstwy, na wierzchu rozłóż ser.","Piecz w 190°C przez 35–40 minut, aż płaty będą miękkie, a wierzch rumiany. Odstaw na 10 minut przed krojeniem."],"minutes":110,"equipment":["oven","pot","stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":110},{"id":30075,"name":"Spaghetti carbonara z guanciale i pecorino","meal":"Obiad","kind":"pork","calories":778,"protein":42,"carbs":10,"fat":62,"ingredients":[["Spaghetti suche",110.0,1.65],["Guanciale",75.0,1.12],["Jajko",2.0,2.1],["Ser pecorino romano",45.0,1.17],["Pieprz czarny",2.0,0.03],["Woda do makaronu",700.0,8.4],["Sól",2.0,0.0]],"steps":["Zagotuj wodę, lekko ją posól i ugotuj spaghetti al dente zgodnie z czasem na opakowaniu. Zachowaj 100 ml wody z gotowania.","Guanciale pokrój w niewielkie słupki. Smaż na suchej patelni 6–8 minut na średnim ogniu, aż tłuszcz się wytopi, a mięso zrumieni.","W misce roztrzep jajka ze startym pecorino i świeżo mielonym pieprzem, tworząc gęstą pastę.","Zdejmij patelnię z ognia. Wymieszaj gorący makaron z guanciale, odczekaj 30 sekund, dodaj masę jajeczną i energicznie mieszaj, dolewając po łyżce wody z makaronu.","Powinien powstać jedwabisty sos, a nie jajecznica. Podaj natychmiast, bez dodatku śmietany."],"minutes":35,"equipment":["pot","stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":35},{"id":30076,"name":"Indyjskie butter chicken w pomidorowym sosie","meal":"Obiad","kind":"chicken","calories":1096,"protein":57,"carbs":96,"fat":51,"ingredients":[["Pierś z kurczaka",190.0,4.94],["Jogurt naturalny",90.0,1.35],["Passata pomidorowa",200.0,1.6],["Śmietanka 30%",70.0,0.84],["Masło",25.0,1.38],["Cebula",65.0,0.33],["Czosnek",8.0,0.12],["Imbir świeży",12.0,0.18],["Garam masala",5.0,0.07],["Papryka słodka",4.0,0.05],["Sól",3.0,0.0],["Ryż basmati suchy",85.0,0.85]],"steps":["Kurczaka pokrój na kawałki 3 cm, wymieszaj z jogurtem, połową garam masala i papryką; marynuj 20 minut.","Ryż basmati opłucz i ugotuj w osolonej wodzie zgodnie z opakowaniem, zwykle 10–12 minut. Na patelni zrumień kurczaka 5 minut, zdejmij.","W maśle zeszklij posiekaną cebulę przez 5 minut, dodaj czosnek i imbir na minutę. Wlej passatę, dodaj resztę garam masala i gotuj 10 minut.","Zblenduj sos na gładko, dodaj śmietankę i kurczaka. Duś 10–12 minut do minimum 74°C wewnątrz mięsa.","Dopraw solą, podawaj z ugotowanym ryżem i kremowym sosem."],"minutes":80,"equipment":["pot","stove","blender"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":80},{"id":30077,"name":"Chicken tikka masala z aromatycznym ryżem","meal":"Obiad","kind":"chicken","calories":988,"protein":58,"carbs":97,"fat":39,"ingredients":[["Pierś z kurczaka",190.0,4.94],["Jogurt naturalny",110.0,1.65],["Passata pomidorowa",210.0,1.68],["Cebula",65.0,0.33],["Imbir świeży",12.0,0.18],["Czosnek",8.0,0.12],["Garam masala",6.0,0.09],["Kumin mielony",3.0,0.04],["Papryka ostra",2.0,0.02],["Olej rzepakowy",12.0,0.13],["Śmietanka 30%",55.0,0.66],["Ryż basmati",85.0,0.85],["Sól",3.0,0.0]],"steps":["Kurczaka pokrój w kostkę, wymieszaj z połową jogurtu, połową garam masala, kuminem i papryką. Marynuj 20 minut.","Kawałki mięsa ułóż na blasze i piecz 12–15 minut w 220°C, do wyraźnego zrumienienia brzegów. W tym czasie ugotuj ryż.","Na oleju zeszklij cebulę 5 minut, dodaj imbir, czosnek i resztę przypraw na minutę. Wlej passatę i gotuj 12 minut.","Do sosu dodaj resztę jogurtu, śmietankę oraz kawałki upieczonego kurczaka. Podgrzewaj 5 minut i sprawdź minimum 74°C w mięsie.","Dopraw solą; podawaj z ryżem i gęstym, korzennym sosem."],"minutes":85,"equipment":["oven","pot","stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":85},{"id":30078,"name":"Grecki gyros z kurczaka w picie i tzatziki","meal":"Obiad","kind":"chicken","calories":567,"protein":50,"carbs":30,"fat":26,"ingredients":[["Pierś z kurczaka",190.0,4.94],["Pita pszenna",110.0,1.65],["Ogórek świeży",100.0,1.0],["Jogurt grecki",100.0,1.5],["Czosnek",6.0,0.09],["Pomidor",110.0,0.88],["Cebula czerwona",45.0,0.23],["Oliwa",16.0,0.64],["Oregano",3.0,0.04],["Sok z cytryny",15.0,0.18],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Kurczaka pokrój w cienkie paski. Wymieszaj z połową oliwy, oregano, pieprzem, sokiem z cytryny i szczyptą soli; marynuj 15 minut.","Ogórek zetrzyj, odciśnij wodę. Wymieszaj z jogurtem, rozgniecionym czosnkiem i resztą oliwy, tworząc tzatziki.","Na gorącej patelni smaż kurczaka 8–10 minut, mieszając, aż mięso osiągnie co najmniej 74°C. Pomidora i cebulę pokrój w plasterki.","Pitę ogrzej 2 minuty na suchej patelni, natnij i napełnij kurczakiem, pomidorem, cebulą i sosem tzatziki.","Podawaj od razu, gdy pita jest jeszcze miękka."],"minutes":55,"equipment":["stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":55},{"id":30079,"name":"Grecka moussaka z bakłażanem i wołowiną","meal":"Obiad","kind":"beef","calories":1280,"protein":70,"carbs":81,"fat":73,"ingredients":[["Bakłażan",260.0,3.38],["Ziemniaki",140.0,0.63],["Mięso mielone wołowe",170.0,11.56],["Passata pomidorowa",150.0,1.2],["Cebula",75.0,0.38],["Oliwa",20.0,0.8],["Mleko",160.0,0.64],["Masło",15.0,0.82],["Mąka pszenna",18.0,0.09],["Jajko",1.0,1.05],["Ser żółty",50.0,1.3],["Cynamon",1.0,0.01],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Bakłażana pokrój w plastry 7 mm, posól lekko i odstaw na 15 minut, potem osusz. Ziemniaki pokrój cienko i podgotuj 8 minut.","Plastry bakłażana posmaruj połową oliwy i piecz w 200°C przez 18 minut. Na reszcie oliwy podsmaż cebulę i mięso 8 minut, dolej passatę, cynamon i gotuj 12 minut.","Na maśle z mąką przygotuj jasną zasmażkę minutę, stopniowo dodaj mleko i gotuj 4 minuty. Gdy sos lekko ostygnie, rozmieszaj z jajkiem.","W formie ułóż warstwami ziemniaki, bakłażana, farsz mięsny i resztę bakłażana; polej beszamelem i posyp serem.","Piecz 35–40 minut w 185°C. Odstaw 10 minut przed podaniem, aby warstwy dały się kroić."],"minutes":125,"equipment":["oven","pot","stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":125},{"id":30080,"name":"Kurczak teriyaki z ryżem i brokułem","meal":"Obiad","kind":"chicken","calories":873,"protein":52,"carbs":117,"fat":19,"ingredients":[["Pierś z kurczaka",190.0,4.94],["Ryż jaśminowy",90.0,0.9],["Brokuł",160.0,2.4],["Sos sojowy",35.0,0.53],["Miód",20.0,0.5],["Ocet ryżowy",18.0,0.18],["Imbir świeży",12.0,0.18],["Czosnek",6.0,0.09],["Olej sezamowy",12.0,0.13],["Skrobia kukurydziana",8.0,0.12],["Woda",100.0,0.0]],"steps":["Ryż wypłucz i ugotuj w osolonej wodzie zgodnie z opakowaniem. Brokuł podziel na różyczki i gotuj na parze 5–6 minut.","W miseczce połącz sos sojowy, miód, ocet ryżowy, starty imbir, czosnek, wodę i skrobię; dokładnie wymieszaj.","Kurczaka pokrój na kawałki 2 cm i obsmaż na rozgrzanym oleju sezamowym przez 6–8 minut.","Wlej sos na patelnię, mieszaj 3–4 minuty do uzyskania gładkiej, lśniącej glazury; sprawdź co najmniej 74°C wewnątrz mięsa.","Podawaj teriyaki na ryżu z brokułem obok; polej mięso sosem z patelni."],"minutes":45,"equipment":["pot","stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":45},{"id":30081,"name":"Francuskie boeuf bourguignon w czerwonym winie","meal":"Obiad","kind":"beef","calories":1003,"protein":63,"carbs":31,"fat":53,"ingredients":[["Wołowina na gulasz",230.0,15.64],["Boczek wędzony",45.0,2.16],["Pieczarki",100.0,1.2],["Cebula",85.0,0.42],["Marchew",75.0,0.38],["Czerwone wino wytrawne",170.0,2.55],["Bulion wołowy gotowy",200.0,13.6],["Koncentrat pomidorowy",15.0,0.12],["Mąka pszenna",12.0,0.06],["Masło",12.0,0.66],["Liść laurowy",1.0,0.01],["Tymianek",2.0,0.03],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Wołowinę osusz i pokrój w kostkę 3 cm. Boczek pokrój w paski, cebulę i marchew w kostkę, pieczarki na ćwiartki.","W ciężkim garnku wytop boczek przez 5 minut, wyjmij. Obsmaż wołowinę na tłuszczu po 2 minuty z każdej strony, partiami, a potem dodaj mąkę i wymieszaj.","Dodaj cebulę, marchew, koncentrat, czerwone wino, bulion, liść laurowy i tymianek. Przykryj i duś na małym ogniu 120–140 minut.","Na osobnej patelni rozpuść masło i zrumień pieczarki przez 6–7 minut. Włóż je razem z boczkiem do duszonej wołowiny na ostatnie 15 minut.","Dopraw pieprzem i solą. Mięso powinno łatwo rozdzielać się widelcem, a sos być gęsty i ciemny."],"minutes":190,"equipment":["pot","stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":190},{"id":30082,"name":"Hiszpańska paella valenciana z kurczakiem i fasolką","meal":"Obiad","kind":"chicken","calories":1398,"protein":78,"carbs":177,"fat":39,"ingredients":[["Ryż do paelli",110.0,1.1],["Udko z kurczaka bez kości",180.0,4.68],["Fasolka szparagowa",110.0,1.21],["Fasola biała ugotowana",85.0,0.94],["Pomidory starte",110.0,0.88],["Oliwa",15.0,0.6],["Bulion drobiowy gotowy",340.0,5.1],["Szafran",1.0,0.01],["Papryka słodka",3.0,0.04],["Sól",3.0,0.0],["Cytryna",40.0,0.48]],"steps":["Kurczaka pokrój w większe kawałki, fasolkę szparagową oczyść i przetnij na pół. Bulion podgrzej razem z szafranem.","Na szerokiej patelni do paelli rozgrzej oliwę, obsmaż kurczaka przez 7–8 minut, aż się zrumieni. Dodaj fasolkę i smaż 3 minuty.","Wmieszaj starte pomidory i paprykę mieloną, gotuj 4 minuty. Wsyp suchy ryż, wyrównaj jego warstwę i zalej gorącym bulionem.","Gotuj bez mieszania przez 15–18 minut, aż ryż wchłonie płyn. Dodaj ugotowaną fasolę na ostatnie 5 minut; mięso musi osiągnąć co najmniej 74°C.","Wyłącz ogień, przykryj paellę na 5 minut i podawaj z cząstkami cytryny."],"minutes":75,"equipment":["stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":75},{"id":30083,"name":"Brytyjskie fish and chips z sosem tatarskim","meal":"Obiad","kind":"fish","calories":1229,"protein":53,"carbs":128,"fat":51,"ingredients":[["Filet z dorsza",200.0,12.0],["Ziemniaki",260.0,1.17],["Mąka pszenna",100.0,0.5],["Piwo jasne",140.0,2.1],["Proszek do pieczenia",3.0,0.04],["Olej rzepakowy do smażenia",550,6.05],["Ogórek konserwowy",40.0,1.04],["Majonez",35.0,0.53],["Sok z cytryny",15.0,0.18],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Ziemniaki obierz, pokrój w grube frytki, przepłucz w zimnej wodzie i osusz. Dorsza osusz oraz dopraw solą i pieprzem.","W misce połącz mąkę z proszkiem i bardzo zimnym piwem. Mieszaj krótko, aby powstało gęste ciasto bez dużych grudek.","W głębokim garnku rozgrzej olej do 170°C. Frytki smaż partiami 7–9 minut, potem odsącz i utrzymuj w cieple.","Dorsza zanurz w cieście piwnym i smaż w 175°C przez 5–7 minut, aż ciasto będzie złociste, a ryba w środku osiągnie co najmniej 63°C.","Majonez wymieszaj z posiekanym ogórkiem i sokiem z cytryny. Podawaj rybę z frytkami oraz sosem tatarskim."],"minutes":55,"equipment":["stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":55},{"id":30084,"name":"Teksańskie chili con carne z fasolą","meal":"Obiad","kind":"beef","calories":754,"protein":55,"carbs":56,"fat":33,"ingredients":[["Mięso mielone wołowe",180.0,12.24],["Fasola czerwona ugotowana",150.0,1.65],["Pomidory krojone",200.0,1.6],["Cebula",85.0,0.42],["Papryka czerwona",130.0,1.56],["Czosnek",7.0,0.1],["Olej rzepakowy",12.0,0.13],["Kumin mielony",4.0,0.06],["Papryka wędzona",3.0,0.04],["Chili mielone",2.0,0.03],["Woda",150.0,0.0],["Sól",3.0,0.0]],"steps":["Cebulę i paprykę pokrój w kostkę, czosnek posiekaj. Fasolę odcedź i opłucz, jeśli jest z puszki.","W garnku rozgrzej olej, podsmaż cebulę 5 minut, dodaj mięso mielone i smaż 8 minut, rozdrabniając grudki, aż straci surowy kolor.","Dodaj paprykę, czosnek, kumin, paprykę wędzoną i chili, smaż minutę. Dołóż pomidory i wodę, gotuj 25 minut na małym ogniu.","Dodaj ugotowaną fasolę i gotuj kolejne 10 minut, aż sos będzie gęsty, a mięso całkowicie ugotowane.","Dopraw solą i podawaj gorące; bez niepotrzebnego zagęszczania mąką."],"minutes":75,"equipment":["pot","stove"],"cuisine":"świat","category24":"Mięsa i ryby","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":75},{"id":30085,"name":"Włoskie risotto alla milanese z szafranem i parmezanem","meal":"Obiad","kind":"veg","calories":920,"protein":29,"carbs":99,"fat":38,"ingredients":[["Ryż arborio",110.0,1.1],["Bulion warzywny gotowy",420.0,6.3],["Cebula szalotka",55.0,0.28],["Masło",30.0,1.65],["Parmezan",45.0,0.68],["Białe wino wytrawne",70.0,1.05],["Szafran",1.0,0.01],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Podgrzej gotowy bulion do łagodnego wrzenia i rozprowadź w nim szafran. Jeśli używasz koncentratu bulionowego, rozpuść go wcześniej w wodzie zgodnie z etykietą.","Na patelni rozpuść połowę masła, zeszklij drobno posiekaną szalotkę przez 4 minuty, wsyp suchy ryż i smaż 2 minuty, mieszając.","Wlej białe wino, odparuj przez 2 minuty. Następnie dolewaj po chochli gorącego bulionu, mieszając i czekając, aż ryż wchłonie płyn.","Powtarzaj dodawanie bulionu 17–20 minut, aż ryż będzie al dente, a risotto lekko płynne. Zdejmij z ognia.","Wmieszaj resztę masła i starty parmezan, dopraw pieprzem i solą, podawaj natychmiast na płaskim talerzu."],"minutes":50,"equipment":["stove"],"cuisine":"świat","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":50},{"id":30086,"name":"Włoskie gnocchi ziemniaczane z domowym pesto bazyliowym","meal":"Obiad","kind":"veg","calories":1255,"protein":40,"carbs":129,"fat":64,"ingredients":[["Ziemniaki",300.0,1.35],["Mąka pszenna",95.0,0.47],["Jajko",1.0,1.05],["Bazylia świeża",35.0,0.53],["Parmezan",40.0,0.6],["Orzeszki piniowe",20.0,0.3],["Oliwa",35.0,1.4],["Czosnek",5.0,0.07],["Sól",3.0,0.0],["Woda",700.0,0.0]],"steps":["Ziemniaki ugotuj w mundurkach 25 minut, obierz jeszcze ciepłe, przeciśnij przez praskę i ostudź.","Zagnieć ziemniaki z mąką, jajkiem i połową soli krótko, do połączenia. Formuj wałki grubości 2 cm, pokrój na poduszeczki i odciśnij na nich rowki widelcem.","Bazylię, orzeszki piniowe, parmezan, czosnek i oliwę zmiksuj pulsacyjnie na gęste pesto. Nie podgrzewaj pesto, by zachowało zapach.","Gnocchi gotuj partiami w delikatnie wrzącej osolonej wodzie około 2 minuty od wypłynięcia.","Odcedź i wymieszaj jeszcze gorące gnocchi z pesto oraz łyżką wody z gotowania, by powstał sos."],"minutes":75,"equipment":["pot","stove","blender"],"cuisine":"świat","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":75},{"id":30087,"name":"Szakszuka z pomidorami, papryką i jajkami","meal":"Obiad","kind":"egg","calories":482,"protein":24,"carbs":27,"fat":29,"ingredients":[["Jajko",3.0,3.15],["Pomidory krojone",230.0,1.84],["Papryka czerwona",115.0,1.38],["Cebula",70.0,0.35],["Czosnek",7.0,0.1],["Oliwa",14.0,0.56],["Kumin mielony",3.0,0.04],["Papryka słodka",3.0,0.04],["Natka pietruszki",10.0,0.15],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Cebulę i paprykę pokrój w drobną kostkę, czosnek posiekaj. Na patelni rozgrzej oliwę i smaż cebulę 5 minut, po czym dodaj paprykę na kolejne 6 minut.","Dodaj czosnek, kumin i słodką paprykę, mieszaj 30 sekund. Wlej krojone pomidory i duś na małym ogniu 12–15 minut, aż sos zgęstnieje.","Łyżką zrób trzy wgłębienia, wbij do każdego po jajku. Przykryj patelnię i gotuj około 5–7 minut, aż białka będą ścięte.","Posól, dodaj pieprz i natkę pietruszki. Podawaj bez mieszania jajek z sosem, aby pozostały w całości."],"minutes":40,"equipment":["stove"],"cuisine":"świat","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":40},{"id":30088,"name":"Bliskowschodni falafel z namoczonej ciecierzycy","meal":"Obiad","kind":"veg","calories":682,"protein":31,"carbs":107,"fat":17,"ingredients":[["Ciecierzyca sucha",135.0,1.49],["Cebula",75.0,0.38],["Czosnek",9.0,0.14],["Natka pietruszki",25.0,0.38],["Kolendra świeża",18.0,0.27],["Kumin mielony",4.0,0.06],["Mąka z ciecierzycy",20.0,0.1],["Olej rzepakowy do smażenia",40.0,0.44],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Suchą ciecierzycę zalej dużą ilością zimnej wody na 12 godzin, następnie odcedź i osusz. Nie gotuj jej przed przygotowaniem falafela.","Cebulę i czosnek obierz. Zmiksuj ciecierzycę z cebulą, czosnkiem, natką, kolendrą, kuminem, solą i pieprzem do konsystencji drobnej kaszki, nie gładkiego purée.","Dodaj mąkę z ciecierzycy, wymieszaj i schłodź masę 20 minut. Uformuj małe, zbite kulki lub placuszki.","Na patelni rozgrzej olej do 175°C i smaż falafele partiami po 3–4 minuty na stronę, aż będą ciemnozłote i upieczone w środku.","Osącz na kratce i podawaj gorące. Łączny czas przygotowania uwzględnia wcześniejsze, 12-godzinne moczenie."],"minutes":815,"equipment":["blender","stove"],"cuisine":"świat","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":95},{"id":30089,"name":"Grecka spanakopita ze szpinakiem i fetą","meal":"Obiad","kind":"veg","calories":1149,"protein":38,"carbs":111,"fat":62,"ingredients":[["Ciasto filo",140.0,2.1],["Szpinak świeży",230.0,5.06],["Ser feta",120.0,3.12],["Cebula",65.0,0.33],["Jajko",1.0,1.05],["Oliwa",25.0,1.0],["Koperek",12.0,0.18],["Pieprz",1.0,0.01],["Sól",1.0,0.0]],"steps":["Szpinak opłucz i drobno pokrój. Cebulę posiekaj, na części oliwy smaż 5 minut, dodaj szpinak i duś 4 minuty; odciśnij nadmiar płynu i ostudź.","Wymieszaj szpinak z pokruszoną fetą, koperkiem, roztrzepanym jajkiem i pieprzem; uważaj z solą, bo feta jest słona.","Formę natłuść oliwą, ułóż połowę płatów filo, każdy delikatnie smarując oliwą. Wyłóż farsz, przykryj pozostałymi płatami filo.","Posmaruj wierzch oliwą, natnij porcje nożem. Piecz w 185°C przez 30–35 minut, aż ciasto będzie chrupiące i złote.","Odstaw na 10 minut, żeby farsz się ustabilizował. Pokrój wzdłuż wcześniejszych nacięć."],"minutes":75,"equipment":["oven","stove"],"cuisine":"świat","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":75},{"id":30090,"name":"Francuskie ratatouille z bakłażana, cukinii i pomidorów","meal":"Obiad","kind":"veg","calories":504,"protein":9,"carbs":51,"fat":27,"ingredients":[["Bakłażan",180.0,2.34],["Cukinia",180.0,1.98],["Papryka czerwona",130.0,1.56],["Pomidory",180.0,1.44],["Cebula",80.0,0.4],["Czosnek",7.0,0.1],["Oliwa",25.0,1.0],["Tymianek",3.0,0.04],["Bazylia świeża",12.0,0.18],["Sól",3.0,0.0],["Pieprz",1.0,0.01]],"steps":["Bakłażan, cukinię i paprykę pokrój w kostkę około 2 cm. Pomidory sparz, zdejmij skórkę i pokrój, cebulę posiekaj.","W głębokiej patelni rozgrzej połowę oliwy. Obsmaż bakłażan 7 minut, odłóż. Dodaj pozostałą oliwę i smaż cukinię z papryką przez 6 minut, również odłóż.","Na tej samej patelni podsmaż cebulę 5 minut, dodaj czosnek, pomidory, tymianek, sól i pieprz. Gotuj 7 minut na małym ogniu.","Włóż z powrotem wszystkie warzywa, przykryj i duś 15 minut, aż staną się miękkie, ale nie rozpadną na purée.","Posyp świeżą bazylią. Ratatouille podawaj jako warzywne danie z wyraźnymi kawałkami."],"minutes":70,"equipment":["stove"],"cuisine":"świat","category24":"Mączne i jarskie","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":70},{"id":30091,"name":"Francuskie tosty pain perdu z cynamonem","meal":"Śniadanie","kind":"egg","calories":531,"protein":20,"carbs":44,"fat":29,"ingredients":[["Chleb tostowy",120.0,1.8],["Jajko",2.0,2.1],["Mleko",130.0,0.52],["Masło",20.0,1.1],["Cukier",20.0,0.08],["Cynamon",3.0,0.04],["Truskawki",110.0,1.65]],"steps":["W płaskiej misce roztrzep jajka z mlekiem, cukrem i cynamonem. Truskawki umyj, usuń szypułki i pokrój na połówki.","Kromki chleba zanurz w masie jajecznej po 15–20 sekund na stronę, by nasiąkły, ale nie rozpadły się.","Na patelni roztop połowę masła. Smaż tosty na umiarkowanym ogniu po 3–4 minuty na stronę, dodając pozostałe masło przed kolejną partią.","Przekrój jeden tost: wnętrze powinno być miękkie, lecz nie surowe i mokre od jajka.","Podawaj gorące z pokrojonymi truskawkami."],"minutes":20,"equipment":["stove"],"cuisine":"świat","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":20},{"id":30092,"name":"Amerykańskie pancakes na maślance","meal":"Śniadanie","kind":"breakfast","calories":807,"protein":25,"carbs":122,"fat":23,"ingredients":[["Mąka pszenna",120.0,0.6],["Maślanka",180.0,2.7],["Jajko",1.0,1.05],["Masło",18.0,0.99],["Cukier",20.0,0.08],["Proszek do pieczenia",6.0,0.09],["Soda oczyszczona",2.0,0.03],["Sól",1.0,0.0],["Syrop klonowy",25.0,0.38]],"steps":["W misce wymieszaj mąkę, proszek do pieczenia, sodę, cukier i sól. W drugim naczyniu połącz maślankę, jajko i 10 g roztopionego masła.","Wlej mokre składniki do suchych i mieszaj krótko widelcem: drobne grudki są w porządku. Odstaw ciasto na 5 minut; powinno być gęste i wolno spływać z łyżki.","Patelnię rozgrzej na średnio małym ogniu i natłuść pozostałym masłem. Nakładaj po 2–3 łyżki masy na placek.","Smaż około 2–3 minuty, aż pojawią się pęcherzyki i brzegi się zetną, obróć i smaż jeszcze 1–2 minuty. Nie mieszaj ciasta na patelni.","Układaj pancakes w stosik i polej syropem klonowym."],"minutes":30,"equipment":["stove"],"cuisine":"świat","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":30},{"id":30093,"name":"Turecki menemen z jajkami i zieloną papryką","meal":"Śniadanie","kind":"egg","calories":529,"protein":25,"carbs":33,"fat":32,"ingredients":[["Jajko",3.0,3.15],["Pomidory",240.0,1.92],["Papryka zielona",130.0,1.56],["Cebula",55.0,0.28],["Oliwa",16.0,0.64],["Papryka ostra mielona",2.0,0.02],["Sól",2.0,0.0],["Pieprz",1.0,0.01],["Chleb",90.0,1.35]],"steps":["Pomidory natnij, sparz wrzątkiem, obierz i pokrój w kostkę. Zieloną paprykę oczyść i pokrój na cienkie paski, cebulę posiekaj.","Na patelni rozgrzej oliwę, smaż cebulę 4 minuty, dodaj paprykę i smaż 6 minut. Włóż pomidory, dopraw i duś 8–10 minut, aż sos odparuje.","Jajka roztrzep delikatnie w miseczce i wlej do pomidorów. Mieszaj powoli 2–3 minuty, aż się zetną, ale pozostaną kremowe.","Zdejmij z ognia. Podawaj menemen prosto z patelni z pieczywem; to tureckie danie celowo ma miękkie jajka w sosie, a nie zwarty omlet."],"minutes":30,"equipment":["stove"],"cuisine":"świat","category24":"Śniadania i kolacje","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":30},{"id":30094,"name":"Włoskie tiramisu z kawą i mascarpone","meal":"Deser","kind":"veg","calories":579,"protein":6,"carbs":31,"fat":46,"ingredients":[["Mascarpone",70.0,2.24],["Śmietanka 30%",50.0,0.6],["Cukier puder",17.5,0.07],["Biszkopty savoiardi",55.0,0.82],["Kawa espresso zaparzona",55.0,0.82],["Kakao",6.0,0.23]],"steps":["Ten przepis daje 2 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 140 g Mascarpone; 100 g Śmietanka 30%; 35 g Cukier puder; 110 g Biszkopty savoiardi; 110 g Kawa espresso zaparzona; 12 g Kakao. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Zaparz espresso i całkowicie wystudź w szerokiej misce. Mascarpone i śmietankę trzymaj wcześniej w lodówce.","Ubij zimną śmietankę z cukrem pudrem do miękkich szczytów, dodawaj mascarpone porcjami i krótko mieszaj do gładkiego, gęstego kremu.","Każdy biszkopt zanurz w kawie dosłownie na sekundę z każdej strony, by nasiąkł, ale nie zamienił się w papkę.","Ułóż warstwę biszkoptów w małym naczyniu, rozsmaruj połowę kremu, powtórz warstwy. Przykryj i schładzaj co najmniej 4 godziny.","Przed podaniem oprósz kakao przez sitko. W tej wersji nie ma surowych jaj."],"minutes":275,"equipment":[],"cuisine":"świat","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":35,"k24BatchYield":2},{"id":30095,"name":"Francuskie crème brûlée z chrupiącym karmelem","meal":"Deser","kind":"veg","calories":473,"protein":6,"carbs":26,"fat":37,"ingredients":[["Śmietanka 30%",100.0,1.2],["Żółtko",1.5,1.57],["Cukier",22.5,0.09],["Laska wanilii",1.0,0.01],["Woda do kąpieli wodnej",200.0,0.0]],"steps":["Ten przepis daje 2 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 200 g Śmietanka 30%; 3 szt. Żółtko; 45 g Cukier; 2 g Laska wanilii; 400 g Woda do kąpieli wodnej. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Piekarnik rozgrzej do 150°C. Śmietankę podgrzej z ziarenkami i laską wanilii do momentu pojawienia się pary, nie gotuj; odstaw na 10 minut.","Żółtka wymieszaj z 30 g cukru, bez mocnego ubijania. Wyjmij laskę wanilii, cienkim strumieniem wlej ciepłą śmietankę do żółtek, stale mieszając.","Przelej krem przez sitko do kokilki. Kokilkę ustaw w wysokim naczyniu z gorącą wodą sięgającą do połowy jej wysokości.","Piecz 35–40 minut, aż brzegi będą ścięte, a środek delikatnie drżący. Wyjmij, ostudź i schładzaj co najmniej 2 godziny.","Przed podaniem posyp pozostałym cukrem i skarmelizuj palnikiem kuchennym na chrupiącą, bursztynową skorupkę."],"minutes":205,"equipment":["oven"],"cuisine":"świat","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":85,"k24BatchYield":2},{"id":30096,"name":"Włoska panna cotta waniliowa z sosem malinowym","meal":"Deser","kind":"veg","calories":430,"protein":4,"carbs":27,"fat":32,"ingredients":[["Śmietanka 30%",105.0,1.26],["Mleko",37.5,0.15],["Cukier",17.5,0.07],["Żelatyna spożywcza",3.0,0.04],["Woda",15.0,0.0],["Wanilia ekstrakt",2.0,0.03],["Maliny",55.0,0.82],["Sok z cytryny",5.0,0.06]],"steps":["Ten przepis daje 2 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 210 g Śmietanka 30%; 75 g Mleko; 35 g Cukier; 6 g Żelatyna spożywcza; 30 g Woda; 4 g Wanilia ekstrakt; 110 g Maliny; 10 g Sok z cytryny. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Żelatynę wsyp do 30 ml zimnej wody i odstaw na 10 minut do napęcznienia.","Śmietankę, mleko, cukier i wanilię podgrzej w rondelku do około 75°C, mieszając; nie gotuj.","Zdejmij z ognia i dodaj napęczniałą żelatynę, mieszaj do całkowitego rozpuszczenia. Przelej do szklanki lub foremki i schładzaj 4 godziny.","Maliny podgrzej z sokiem z cytryny przez 5 minut, rozgnieć i przecedź przez sitko, jeśli chcesz usunąć pestki; ostudź.","Panna cottę wyjmij z foremki po krótkim zanurzeniu jej dna w ciepłej wodzie i polej sosem malinowym. Podany czas całkowity uwzględnia obowiązkowe chłodzenie."],"minutes":270,"equipment":["stove"],"cuisine":"świat","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":30,"k24BatchYield":2},{"id":30097,"name":"Amerykańskie brownie z gorzką czekoladą","meal":"Deser","kind":"veg","calories":538,"protein":9,"carbs":48,"fat":34,"ingredients":[["Czekolada gorzka",27.5,1.38],["Masło",21.25,1.17],["Cukier",20.0,0.08],["Jajko",0.5,0.53],["Mąka pszenna",16.25,0.08],["Kakao",4.5,0.17],["Sól",0.25,0.0],["Orzechy włoskie",7.5,0.38]],"steps":["Ten przepis daje 4 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 110 g Czekolada gorzka; 85 g Masło; 80 g Cukier; 2 szt. Jajko; 65 g Mąka pszenna; 18 g Kakao; 1 g Sól; 30 g Orzechy włoskie. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Piekarnik rozgrzej do 175°C. Formę wyłóż papierem, orzechy posiekaj. Czekoladę z masłem rozpuść w kąpieli wodnej, odstaw na 5 minut.","Jajka wymieszaj z cukrem przez 2 minuty. Wlej letnią czekoladę z masłem, następnie wsyp mąkę, kakao i sól.","Krótko wymieszaj tylko do połączenia, dodaj orzechy. Przełóż masę do niewielkiej formy i wyrównaj powierzchnię.","Piecz 22–28 minut, aż brzegi będą ścięte, a środek lekko wilgotny i sprężysty. Brownie powinno być zwarte, ale nie suche jak biszkopt.","Ostudź przynajmniej 30 minut przed pokrojeniem na kwadraty."],"minutes":85,"equipment":["oven","stove"],"cuisine":"świat","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":55,"k24BatchYield":4},{"id":30098,"name":"Turecka baklava z pistacjami i syropem cytrynowym","meal":"Deser","kind":"veg","calories":534,"protein":9,"carbs":61,"fat":29,"ingredients":[["Ciasto filo",38.75,0.58],["Pistacje łuskane",27.5,0.41],["Masło",18.75,1.03],["Cukier",20.0,0.08],["Miód",12.5,0.31],["Woda",22.5,0.0],["Sok z cytryny",6.25,0.07],["Cynamon",0.5,0.01]],"steps":["Ten przepis daje 4 porcje. Aplikacja podaje składniki dla jednej porcji, więc do przygotowania całej receptury odmierz: 155 g Ciasto filo; 110 g Pistacje łuskane; 75 g Masło; 80 g Cukier; 50 g Miód; 90 g Woda; 25 g Sok z cytryny; 2 g Cynamon. Opis dalszych kroków dotyczy tego pełnego zestawu składników.","Piekarnik rozgrzej do 175°C. Pistacje drobno posiekaj i wymieszaj z cynamonem. Masło rozpuść na małym ogniu.","Małą formę natłuść masłem i ułóż połowę płatów filo, każdy osobno smarując masłem; przykrywaj pozostałe płaty wilgotną ściereczką, by nie wyschły.","Rozsyp pistacje na cieście, przykryj pozostałymi płatami filo, smarując je masłem. Ostrym nożem natnij baklavę na romby przed pieczeniem.","Piecz 35–40 minut do głębokiego złotego koloru. W tym czasie zagotuj wodę z cukrem i miodem, gotuj 7 minut, dodaj sok z cytryny.","Gorącą baklavę polej ciepłym syropem, odstaw na co najmniej 2 godziny do wchłonięcia. Podawaj w niewielkich porcjach."],"minutes":225,"equipment":["oven","stove"],"cuisine":"świat","category24":"Ciasta i desery","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":105,"k24BatchYield":4},{"id":30099,"name":"Greckie tzatziki z ogórkiem i czosnkiem","meal":"Dodatek","kind":"veg","calories":260,"protein":9,"carbs":18,"fat":18,"ingredients":[["Jogurt grecki",180.0,2.7],["Ogórek świeży",170.0,1.7],["Czosnek",6.0,0.09],["Oliwa",12.0,0.48],["Koperek",8.0,0.12],["Sok z cytryny",12.0,0.14],["Sól",2.0,0.0],["Pieprz",1.0,0.01]],"steps":["Ogórek dokładnie umyj i zetrzyj na grubych oczkach. Posól lekko i odstaw na 7 minut, następnie mocno odciśnij w dłoniach przez sitko.","Czosnek przeciśnij przez praskę, koperek posiekaj. Połącz z jogurtem greckim, oliwą i sokiem z cytryny.","Dodaj odciśnięty ogórek, dopraw pieprzem oraz resztą soli, delikatnie wymieszaj.","Schładzaj przez 10 minut. Podawaj jako gęsty sos do mięs, pity lub pieczonych warzyw."],"minutes":20,"equipment":[],"cuisine":"świat","category24":"Dodatki i sosy","source24":"autorska receptura","k24Batch":1,"k24CulinaryReview":"do testu w kuchni","activeMinutes":20}];

const ids=new Set(recipes.map(r=>Number(r.id)));
const existingNames=new Set(recipes.map(r=>String(r.name||'').toLocaleLowerCase('pl').trim()));
let added=0;
for(const source of domowePart1){
  if(ids.has(source.id)||existingNames.has(source.name.toLocaleLowerCase('pl').trim()))continue;
  const item={...source,ingredients:source.ingredients.map(x=>[...x]),steps:[...source.steps]};
  item.image=(typeof images==='object'&&images[item.kind])||'./icon.svg';
  recipes.push(item);ids.add(item.id);existingNames.add(item.name.toLocaleLowerCase('pl').trim());added++;
}
window.kamis24DomowePart1Added=added;
window.kamis24DomowePart1Total=domowePart1.length;
try{render()}catch(err){console.error('Kamiś — książka kucharska, partia 1:',err)}
})();
